static const char *
ii42_am_resolve_model_path(Relation index_relation)
{
    const char *model_path;

    model_path = ii42_am_relation_model_path(index_relation);
    if (model_path != NULL && model_path[0] != '\0')
    {
        return model_path;
    }
    if (ii42_semantic_model_path != NULL &&
        ii42_semantic_model_path[0] != '\0')
    {
        return ii42_semantic_model_path;
    }
    if (II42_PACKAGED_MODEL_PATH[0] != '\0')
    {
        return II42_PACKAGED_MODEL_PATH;
    }
    return NULL;
}
