static int
ii42_am_cmp_vocab_item(const void *lhs, const void *rhs)
{
    const ii42_am_vocab_item *left = lhs;
    const ii42_am_vocab_item *right = rhs;

    return strcmp(left->token, right->token);
}

static size_t
ii42_am_generation_vocab_size(
    const ii42_am_cache_entry *entry
)
{
    return entry->generation.index.vocab_size;
}

static const char *
ii42_am_generation_vocab_token(
    const ii42_am_cache_entry *entry,
    uint32_t token_id
)
{
    return entry->generation.index.vocab[token_id];
}

static size_t
ii42_am_vocab_lower_bound(
    const ii42_am_cache_entry *entry,
    const char *token
)
{
    size_t left = 0;
    size_t right;

    right = ii42_am_generation_vocab_size(entry);
    while (left < right)
    {
        size_t mid = left + (right - left) / 2;
        const char *mid_token;

        if (entry->generation.sorted_vocab_ids != NULL)
        {
            mid_token = ii42_am_generation_vocab_token(
                entry,
                entry->generation.sorted_vocab_ids[mid]
            );
        }
        else
        {
            mid_token = entry->generation.sorted_vocab[mid].token;
        }

        if (strcmp(mid_token, token) < 0)
        {
            left = mid + 1;
        }
        else
        {
            right = mid;
        }
    }

    return left;
}

static const char *
ii42_am_sorted_vocab_token(
    const ii42_am_cache_entry *entry,
    size_t pos
)
{
    if (entry->generation.sorted_vocab_ids != NULL)
    {
        return ii42_am_generation_vocab_token(
            entry,
            entry->generation.sorted_vocab_ids[pos]
        );
    }
    return entry->generation.sorted_vocab[pos].token;
}

static uint32_t
ii42_am_sorted_vocab_token_id(
    const ii42_am_cache_entry *entry,
    size_t pos
)
{
    if (entry->generation.sorted_vocab_ids != NULL)
    {
        return entry->generation.sorted_vocab_ids[pos];
    }
    return entry->generation.sorted_vocab[pos].token_id;
}

static bool
ii42_am_checked_mul_size(size_t a, size_t b, size_t *out)
{
    if (a == 0 || b == 0)
    {
        *out = 0;
        return true;
    }

    if (a > ((size_t) -1) / b)
    {
        return false;
    }

    *out = a * b;
    return true;
}

static bool
ii42_am_checked_add_size(size_t a, size_t b, size_t *out)
{
    if (a > ((size_t) -1) - b)
    {
        return false;
    }

    *out = a + b;
    return true;
}

