static void
ii42_am_ensure_term_entry_capacity(
    ii42_am_term_entry_builder *builder
)
{
    if (builder->len == builder->capacity)
    {
        size_t new_capacity =
            builder->capacity == 0 ? 1024 : builder->capacity * 2;
        size_t bytes;

        if (new_capacity < builder->capacity ||
            !ii42_am_checked_mul_size(
                new_capacity,
                sizeof(*builder->entries),
                &bytes))
        {
            ereport(ERROR, (errmsg("ii42 compact build is too large")));
        }
        if (builder->entries == NULL)
        {
            builder->entries = palloc(bytes);
        }
        else
        {
            builder->entries = repalloc(builder->entries, bytes);
        }
        builder->capacity = new_capacity;
    }
}

