static bool
ii42_am_work_hint_low_debt_due(const ii42_am_work_hint_token *token)
{
    TimestampTz now;

    if (token == NULL || token->maintenance_first_marked_at == 0)
    {
        return false;
    }
    now = GetCurrentTimestamp();
    return token->maintenance_first_marked_at <= now &&
        TimestampDifferenceExceeds(
            token->maintenance_first_marked_at,
            now,
            ii42_am_low_debt_interval()
        );
}

static bool
ii42_am_work_hint_accelerator_retry_allowed(
    const ii42_am_work_hint_token *token
)
{
    return token == NULL || token->accelerator_retry_after == 0 ||
        token->accelerator_retry_after <= GetCurrentTimestamp();
}

static uint64
ii42_am_posting_heat_now_ms(void)
{
    TimestampTz now = GetCurrentTimestamp();

    return now > 0 ? (uint64) now / UINT64_C(1000) : UINT64_C(1);
}

static uint64
ii42_am_posting_heat_rewrite_benefit_bytes(
    const ii42_posting_heat_entry *heat,
    uint32 surface_reduction,
    bool completes_current_coverage
)
{
    uint64 benefit_bytes;

    if (heat == NULL || surface_reduction == 0)
    {
        return 0;
    }
    benefit_bytes = ii42_u64_saturating_mul(
        heat->root_heat,
        surface_reduction
    );
    benefit_bytes = ii42_u64_saturating_mul(
        benefit_bytes,
        II42_AM_POSTING_HEAT_BENEFIT_BYTES
    );

    /*
     * A complete neutral fold can become the exact-root impact hot path.
     * Charge its rewrite against page work actually observed on this root,
     * not against corpus size or an assumed query frequency.
     */
    if (completes_current_coverage &&
        heat->impact_specialization_ready)
    {
        uint64 unpruned_blocks =
            heat->blocks_considered >= heat->blocks_skipped
                ? heat->blocks_considered - heat->blocks_skipped
                : 0;
        uint64 observed_page_bytes =
            ii42_u64_saturating_mul(
                unpruned_blocks,
                BLCKSZ
            );

        benefit_bytes = Max(benefit_bytes, observed_page_bytes);
    }
    return benefit_bytes;
}

static ii42_am_local_posting_heat *
ii42_am_local_posting_heat_find(
    Oid index_oid,
    uint32 term_id,
    bool create
)
{
    ii42_am_local_posting_heat *free_entry = NULL;

    for (uint32 index = 0;
         index < II42_AM_POSTING_HEAT_LOCAL_CAPACITY;
         index++)
    {
        ii42_am_local_posting_heat *entry =
            &ii42_am_local_posting_heat_entries[index];

        if (entry->valid &&
            entry->observation.database_id == (uint32) MyDatabaseId &&
            entry->observation.index_id == (uint32) index_oid &&
            entry->observation.term_id == term_id)
        {
            return entry;
        }
        if (!entry->valid && free_entry == NULL)
        {
            free_entry = entry;
        }
    }
    if (!create || free_entry == NULL)
    {
        return NULL;
    }
    memset(free_entry, 0, sizeof(*free_entry));
    free_entry->valid = true;
    free_entry->observation.database_id = (uint32) MyDatabaseId;
    free_entry->observation.index_id = (uint32) index_oid;
    free_entry->observation.term_id = term_id;
    return free_entry;
}

static void
ii42_am_posting_heat_flush_local(void)
{
    ii42_posting_heat_observation observations[
        II42_AM_POSTING_HEAT_LOCAL_CAPACITY
    ];
    Oid scheduled_indexes[II42_AM_POSTING_HEAT_LOCAL_CAPACITY];
    size_t observation_count = 0;
    size_t scheduled_count;

    for (uint32 index = 0;
         index < II42_AM_POSTING_HEAT_LOCAL_CAPACITY;
         index++)
    {
        const ii42_am_local_posting_heat *local =
            &ii42_am_local_posting_heat_entries[index];

        if (local->valid)
        {
            observations[observation_count++] = local->observation;
        }
    }
    scheduled_count = ii42_am_scheduler_posting_heat_merge(
        observations,
        observation_count,
        scheduled_indexes,
        lengthof(scheduled_indexes)
    );
    memset(
        ii42_am_local_posting_heat_entries,
        0,
        sizeof(ii42_am_local_posting_heat_entries)
    );
    ii42_am_local_posting_heat_query_count = 0;
    for (size_t index = 0; index < scheduled_count; index++)
    {
        ii42_am_work_hint_mark(
            scheduled_indexes[index],
            II42_AM_WORK_HINT_MAINTENANCE
        );
    }
}

static void
ii42_am_posting_heat_add_fold_range(
    const ii42_segment_storage_snapshot *snapshot,
    uint32 bundle_index,
    uint32 first_run,
    uint32 run_count,
    uint64 *posting_count,
    uint64 *block_count
)
{
    const ii42_term_fold_bundle *bundle;

    if (snapshot == NULL || posting_count == NULL ||
        block_count == NULL || run_count == 0 ||
        bundle_index >= snapshot->term_fold_bundle_count)
    {
        return;
    }
    bundle = &snapshot->term_fold_bundles[bundle_index];
    if (first_run > bundle->run_count ||
        run_count > bundle->run_count - first_run)
    {
        return;
    }
    for (uint32 run_offset = 0;
         run_offset < run_count;
         run_offset++)
    {
        const ii42_term_fold_run *run =
            &bundle->runs[first_run + run_offset];

        *posting_count = ii42_u64_saturating_add(
            *posting_count,
            run->posting_count
        );
        *block_count = ii42_u64_saturating_add(
            *block_count,
            run->block_count
        );
    }
}

static bool
ii42_am_posting_heat_observe_term(
    Oid index_oid,
    uint64 root_id,
    uint32 term_id,
    uint64 query_count,
    uint32 extent_count,
    uint64 posting_count,
    uint64 block_count,
    bool impact_specialization_ready,
    bool hot_cache_republish_ready,
    uint64 blocks_considered,
    uint64 blocks_scored,
    uint64 blocks_skipped,
    uint64 postings_scored,
    uint64 observed_at_ms
)
{
    ii42_am_local_posting_heat *local;

    ii42_am_ensure_exit_callback();
    local = ii42_am_local_posting_heat_find(index_oid, term_id, true);
    if (local == NULL)
    {
        /*
         * Heat is optional and lossy. Keep the first bounded key set and
         * drop excess observations until the normal query-count flush.
         */
        return false;
    }
    local->observation.query_count =
        ii42_u64_saturating_add(
            local->observation.query_count,
            query_count
        );
    if (root_id > local->observation.root_id)
    {
        local->observation.root_id = root_id;
        local->observation.root_query_count = query_count;
        local->observation.extent_transition_work = 0;
        local->observation.posting_work = 0;
        local->observation.block_work = 0;
        local->observation.blocks_considered = 0;
        local->observation.blocks_scored = 0;
        local->observation.blocks_skipped = 0;
        local->observation.postings_scored = 0;
    }
    else if (root_id == local->observation.root_id)
    {
        local->observation.root_query_count =
            ii42_u64_saturating_add(
                local->observation.root_query_count,
                query_count
            );
    }
    if (root_id == local->observation.root_id)
    {
        local->observation.extent_transition_work =
            ii42_u64_saturating_add(
                local->observation.extent_transition_work,
                ii42_u64_saturating_mul(
                    extent_count > 0 ? extent_count - 1 : 0,
                    query_count
                )
            );
        local->observation.posting_work =
            ii42_u64_saturating_add(
                local->observation.posting_work,
                ii42_u64_saturating_mul(
                    posting_count,
                    query_count
                )
            );
        local->observation.block_work =
            ii42_u64_saturating_add(
                local->observation.block_work,
                ii42_u64_saturating_mul(
                    block_count,
                    query_count
                )
            );
        local->observation.blocks_considered =
            ii42_u64_saturating_add(
                local->observation.blocks_considered,
                ii42_u64_saturating_mul(
                    blocks_considered,
                    query_count
                )
            );
        local->observation.blocks_scored =
            ii42_u64_saturating_add(
                local->observation.blocks_scored,
                ii42_u64_saturating_mul(
                    blocks_scored,
                    query_count
                )
            );
        local->observation.blocks_skipped =
            ii42_u64_saturating_add(
                local->observation.blocks_skipped,
                ii42_u64_saturating_mul(
                    blocks_skipped,
                    query_count
                )
            );
        local->observation.postings_scored =
            ii42_u64_saturating_add(
                local->observation.postings_scored,
                ii42_u64_saturating_mul(
                    postings_scored,
                    query_count
                )
            );
        local->observation.last_extent_count = extent_count;
        local->observation.last_block_count =
            block_count > UINT32_MAX
                ? UINT32_MAX
                : (uint32) block_count;
        local->observation.last_posting_count = posting_count;
        local->observation.impact_specialization_ready =
            impact_specialization_ready;
        local->observation.hot_cache_republish_ready =
            hot_cache_republish_ready;
        local->observation.observed_at_ms = observed_at_ms;
    }
    return true;
}

static void
ii42_am_posting_heat_observe(
    Relation index_relation,
    ii42_am_cache_entry *entry,
    const uint32_t *query_ids,
    size_t query_len,
    const ii42_blockmax_stats *blockmax_stats
)
{
    const ii42_segment_storage_snapshot *snapshot;
    ii42_am_hot_fold_view hot_fold;
    uint32 observed_term_ids[II42_AM_POSTING_HEAT_LOCAL_CAPACITY];
    size_t observed_term_count = 0;
    uint64 sampled_query_count;
    uint64 observed_at_ms;
    bool hot_fold_attached = false;
    bool inspect_hot_fold;
    bool exact_term_work = query_len == 1;

    if (!ii42_am_scheduler_available() ||
        entry == NULL ||
        entry->generation.segment_snapshot == NULL ||
        (query_len > 0 && query_ids == NULL))
    {
        return;
    }
    snapshot = entry->generation.segment_snapshot;
    if (snapshot->root.root_id == 0)
    {
        return;
    }
    ii42_am_local_posting_heat_query_count++;
    if (ii42_am_local_posting_heat_query_count <
        II42_AM_POSTING_HEAT_FLUSH_QUERY_COUNT)
    {
        return;
    }
    sampled_query_count = ii42_am_local_posting_heat_query_count;
    ii42_am_hot_fold_view_init(&hot_fold);
    inspect_hot_fold = true;
    if (inspect_hot_fold &&
        index_relation != NULL &&
        snapshot->root.active_l0.record_count == 0 &&
        snapshot->root.pending_l0.record_count == 0)
    {
        hot_fold_attached = ii42_am_hot_fold_attach(
            index_relation,
            &entry->generation.meta,
            &hot_fold
        );
    }
    observed_at_ms = ii42_am_posting_heat_now_ms();

    for (size_t query_index = 0;
         query_index < query_len;
         query_index++)
    {
        uint32 term_id = query_ids[query_index];
        const ii42_term_extent_list *term;
        uint64 posting_count = 0;
        uint64 block_count = 0;
        bool impact_specialization_ready = false;
        bool hot_cache_republish_ready = false;
        bool duplicate = false;

        if (term_id >= snapshot->read_view.vocab_size)
        {
            continue;
        }
        for (size_t prior_index = 0;
             prior_index < observed_term_count;
             prior_index++)
        {
            if (observed_term_ids[prior_index] == term_id)
            {
                duplicate = true;
                break;
            }
        }
        if (duplicate)
        {
            continue;
        }
        term = &snapshot->read_view.terms[term_id];
        for (size_t extent_index = 0;
             extent_index < term->len;
             extent_index++)
        {
            posting_count = ii42_u64_saturating_add(
                posting_count,
                term->extents[extent_index].len
            );
            block_count = ii42_u64_saturating_add(
                block_count,
                term->extents[extent_index].block_count
            );
        }
        if (snapshot->term_fold_plans != NULL)
        {
            const ii42_term_fold_read_plan *plan =
                &snapshot->term_fold_plans[term_id];

            if (plan->impact_run_count > 0)
            {
                ii42_am_posting_heat_add_fold_range(
                    snapshot,
                    plan->impact_bundle_index,
                    plan->impact_first_run,
                    plan->impact_run_count,
                    &posting_count,
                    &block_count
                );
                hot_cache_republish_ready =
                    inspect_hot_fold &&
                    ii42_am_preload_cache_available() &&
                    (!hot_fold_attached ||
                     ii42_am_hot_fold_find_term(
                         &hot_fold,
                         term_id
                     ) == NULL);
            }
            else
            {
                ii42_am_posting_heat_add_fold_range(
                    snapshot,
                    plan->neutral_bundle_index,
                    plan->neutral_first_run,
                    plan->neutral_run_count,
                    &posting_count,
                    &block_count
                );
                ii42_am_posting_heat_add_fold_range(
                    snapshot,
                    plan->neutral_minor_bundle_index,
                    plan->neutral_minor_first_run,
                    plan->neutral_minor_run_count,
                    &posting_count,
                    &block_count
                );
                impact_specialization_ready =
                    (plan->neutral_run_count > 0 ||
                     plan->neutral_minor_run_count > 0) &&
                    !ii42_method_requires_nonoccurrence(
                        snapshot->index_metadata.params.method) &&
                    snapshot->root.active_l0.record_count == 0 &&
                    snapshot->root.pending_l0.record_count == 0;
            }
        }

        if (!ii42_am_posting_heat_observe_term(
                entry->index_oid,
                snapshot->root.root_id,
                term_id,
                sampled_query_count,
                term->len > UINT32_MAX
                    ? UINT32_MAX
                    : (uint32) term->len,
                posting_count,
                block_count,
                impact_specialization_ready,
                hot_cache_republish_ready,
                blockmax_stats == NULL || !exact_term_work
                    ? 0
                    : blockmax_stats->blocks_considered,
                blockmax_stats == NULL || !exact_term_work
                    ? 0
                    : blockmax_stats->blocks_scored,
                blockmax_stats == NULL || !exact_term_work
                    ? 0
                    : blockmax_stats->blocks_skipped,
                blockmax_stats == NULL || !exact_term_work
                    ? 0
                    : blockmax_stats->postings_scored,
                observed_at_ms))
        {
            continue;
        }
        if (observed_term_count <
            II42_AM_POSTING_HEAT_LOCAL_CAPACITY)
        {
            observed_term_ids[observed_term_count++] = term_id;
        }
    }

    ii42_am_posting_heat_flush_local();
    ii42_am_hot_fold_view_release(&hot_fold);
}

static void
ii42_am_posting_heat_observe_page_native(
    Relation index_relation,
    const ii42_am_meta_page *meta,
    const ii42_segment_query_context *context,
    const uint32_t *query_ids,
    size_t query_len,
    const ii42_page_query_stats *query_stats
)
{
    ii42_am_hot_fold_view hot_fold;
    uint32 observed_term_ids[II42_AM_POSTING_HEAT_LOCAL_CAPACITY];
    size_t observed_term_count = 0;
    uint64 observed_at_ms;
    bool hot_fold_attached = false;
    bool inspect_hot_fold;
    bool exact_term_work = query_len == 1;

    if (!ii42_am_scheduler_available() ||
        index_relation == NULL || context == NULL ||
        context->root.root_id == 0 ||
        (query_len > 0 && query_ids == NULL))
    {
        return;
    }
    ii42_am_hot_fold_view_init(&hot_fold);
    inspect_hot_fold = exact_term_work &&
        ii42_am_local_posting_heat_query_count + 1 >=
        II42_AM_POSTING_HEAT_FLUSH_QUERY_COUNT;
    if (inspect_hot_fold &&
        meta != NULL &&
        context->root.active_l0.record_count == 0 &&
        context->root.pending_l0.record_count == 0)
    {
        hot_fold_attached = ii42_am_hot_fold_attach(
            index_relation,
            meta,
            &hot_fold
        );
    }
    observed_at_ms = ii42_am_posting_heat_now_ms();
    PG_TRY();
    {
        for (size_t query_index = 0;
             query_index < query_len;
             query_index++)
        {
            ii42_segment_query_term_plan plan;
            uint32 term_id = query_ids[query_index];
            uint64 posting_count = 0;
            uint64 block_count = 0;
            bool lexical_neutral_seen = false;
            bool lexical_impact_seen = false;
            bool hot_cache_republish_ready = false;
            bool duplicate = false;

            if (term_id >= context->manifest.vocab_size)
            {
                continue;
            }
            for (size_t prior_index = 0;
                 prior_index < observed_term_count;
                 prior_index++)
            {
                if (observed_term_ids[prior_index] == term_id)
                {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate)
            {
                continue;
            }
            if (!exact_term_work)
            {
                if (ii42_am_posting_heat_observe_term(
                        RelationGetRelid(index_relation),
                        context->root.root_id,
                        term_id,
                        1,
                        0,
                        0,
                        0,
                        false,
                        false,
                        0,
                        0,
                        0,
                        0,
                        observed_at_ms) &&
                    observed_term_count <
                        II42_AM_POSTING_HEAT_LOCAL_CAPACITY)
                {
                    observed_term_ids[observed_term_count++] = term_id;
                }
                continue;
            }
            ii42_segment_pages_load_query_term_plan(
                index_relation,
                context,
                term_id,
                &plan
            );
            for (uint32 run_index = 0;
                 run_index < plan.run_count;
                 run_index++)
            {
                const ii42_segment_query_run *run = &plan.runs[run_index];

                posting_count = ii42_u64_saturating_add(
                    posting_count,
                    run->posting_count
                );
                block_count = ii42_u64_saturating_add(
                    block_count,
                    run->block_count
                );
                lexical_neutral_seen = lexical_neutral_seen ||
                    run->kind == II42_POSTING_EXTENT_LEXICAL_NEUTRAL;
                lexical_impact_seen = lexical_impact_seen ||
                    run->kind == II42_POSTING_EXTENT_LEXICAL_IMPACT;
            }
            hot_cache_republish_ready =
                inspect_hot_fold &&
                lexical_impact_seen &&
                ii42_am_preload_cache_available() &&
                (!hot_fold_attached ||
                 ii42_am_hot_fold_find_term(&hot_fold, term_id) == NULL);
            if (!ii42_am_posting_heat_observe_term(
                    RelationGetRelid(index_relation),
                    context->root.root_id,
                    term_id,
                    1,
                    plan.run_count,
                    posting_count,
                    block_count,
                    lexical_neutral_seen && !lexical_impact_seen &&
                        !ii42_method_requires_nonoccurrence(
                            context->query_contract.params.method) &&
                        context->root.active_l0.record_count == 0 &&
                        context->root.pending_l0.record_count == 0,
                    hot_cache_republish_ready,
                    query_stats == NULL || !exact_term_work
                        ? 0
                        : query_stats->posting_block_reads,
                    query_stats == NULL || !exact_term_work
                        ? 0
                        : query_stats->posting_block_reads,
                    0,
                    query_stats == NULL || !exact_term_work
                        ? 0
                        : query_stats->postings_examined,
                    observed_at_ms))
            {
                continue;
            }
            if (observed_term_count <
                II42_AM_POSTING_HEAT_LOCAL_CAPACITY)
            {
                observed_term_ids[observed_term_count++] = term_id;
            }
        }

        ii42_am_local_posting_heat_query_count++;
        if (ii42_am_local_posting_heat_query_count >=
            II42_AM_POSTING_HEAT_FLUSH_QUERY_COUNT)
        {
            ii42_am_posting_heat_flush_local();
        }
    }
    PG_FINALLY();
    {
        ii42_am_hot_fold_view_release(&hot_fold);
    }
    PG_END_TRY();
}

