static uint64
ii42_am_elapsed_us(TimestampTz started_at)
{
    TimestampTz finished_at = GetCurrentTimestamp();
    long seconds;
    int microseconds;

    if (started_at == 0 || finished_at <= started_at)
    {
        return 0;
    }
    TimestampDifference(
        started_at,
        finished_at,
        &seconds,
        &microseconds
    );
    if (seconds < 0 || microseconds < 0)
    {
        return 0;
    }
    return (uint64) seconds * UINT64_C(1000000) +
        (uint64) microseconds;
}

static int64
ii42_am_timestamp_age_ms(TimestampTz timestamp)
{
    TimestampTz now = GetCurrentTimestamp();
    long seconds;
    int microseconds;

    if (timestamp == 0 || timestamp > now)
    {
        return -1;
    }
    TimestampDifference(timestamp, now, &seconds, &microseconds);
    if (seconds < 0 || microseconds < 0)
    {
        return -1;
    }
    return (int64) seconds * INT64_C(1000) +
        (int64) microseconds / INT64_C(1000);
}

static int64
ii42_am_timestamp_until_ms(TimestampTz timestamp)
{
    TimestampTz now = GetCurrentTimestamp();
    long seconds;
    int microseconds;

    if (timestamp == 0)
    {
        return -1;
    }
    if (timestamp <= now)
    {
        return 0;
    }
    TimestampDifference(now, timestamp, &seconds, &microseconds);
    if (seconds < 0 || microseconds < 0)
    {
        return -1;
    }
    return (int64) seconds * INT64_C(1000) +
        (int64) microseconds / INT64_C(1000);
}

static char *
ii42_am_semantic_telemetry_json(Oid index_oid, bool enabled)
{
    ii42_am_semantic_telemetry telemetry;
    bool available = ii42_am_scheduler_available();
    bool observed;
    int64 last_attempt_age_ms;
    int64 last_completed_age_ms;
    int64 last_error_age_ms;
    double last_rows_per_second;
    char last_attempt_age_json[32];
    char last_completed_age_json[32];
    char last_error_age_json[32];
    StringInfoData last_error_json;
    char *json;

    memset(&telemetry, 0, sizeof(telemetry));
    observed = enabled &&
        ii42_am_semantic_telemetry_snapshot(index_oid, &telemetry);
    last_attempt_age_ms = ii42_am_timestamp_age_ms(
        telemetry.last_attempt_at
    );
    last_completed_age_ms = ii42_am_timestamp_age_ms(
        telemetry.last_completed_at
    );
    last_error_age_ms = ii42_am_timestamp_age_ms(
        telemetry.last_error_at
    );
    last_rows_per_second = telemetry.last_duration_us > 0
        ? (double) telemetry.last_batch_completed * 1000000.0 /
            (double) telemetry.last_duration_us
        : 0.0;
    snprintf(
        last_attempt_age_json,
        sizeof(last_attempt_age_json),
        last_attempt_age_ms < 0 ? "null" : "%lld",
        (long long) last_attempt_age_ms
    );
    snprintf(
        last_completed_age_json,
        sizeof(last_completed_age_json),
        last_completed_age_ms < 0 ? "null" : "%lld",
        (long long) last_completed_age_ms
    );
    snprintf(
        last_error_age_json,
        sizeof(last_error_age_json),
        last_error_age_ms < 0 ? "null" : "%lld",
        (long long) last_error_age_ms
    );
    initStringInfo(&last_error_json);
    if (telemetry.last_error[0] == '\0')
    {
        appendStringInfoString(&last_error_json, "null");
    }
    else
    {
        escape_json(&last_error_json, telemetry.last_error);
    }
    json = psprintf(
        "{\"available\":%s,\"observed\":%s,"
        "\"attempts\":" UINT64_FORMAT ","
        "\"completed\":" UINT64_FORMAT ","
        "\"retired\":" UINT64_FORMAT ","
        "\"retries\":" UINT64_FORMAT ","
        "\"failures\":" UINT64_FORMAT ","
        "\"last_batch_completed\":%u,"
        "\"last_batch_retired\":%u,"
        "\"last_duration_ms\":%.3f,"
        "\"last_rows_per_second\":%.3f,"
        "\"frontier_scanned_records\":" UINT64_FORMAT ","
        "\"frontier_scanned_bytes\":" UINT64_FORMAT ","
        "\"frontier_xid_lock_windows\":" UINT64_FORMAT ","
        "\"frontier_reconstructions\":" UINT64_FORMAT ","
        "\"last_frontier_scanned_records\":%u,"
        "\"last_frontier_scanned_bytes\":" UINT64_FORMAT ","
        "\"last_frontier_xid_lock_windows\":%u,"
        "\"last_frontier_reconstructed\":%s,"
        "\"last_attempt_age_ms\":%s,"
        "\"last_completed_age_ms\":%s,"
        "\"last_error_age_ms\":%s,\"last_error\":%s}",
        available ? "true" : "false",
        observed ? "true" : "false",
        telemetry.attempts,
        telemetry.completed,
        telemetry.retired,
        telemetry.retries,
        telemetry.failures,
        telemetry.last_batch_completed,
        telemetry.last_batch_retired,
        (double) telemetry.last_duration_us / 1000.0,
        last_rows_per_second,
        telemetry.frontier_scanned_records,
        telemetry.frontier_scanned_bytes,
        telemetry.frontier_xid_lock_windows,
        telemetry.frontier_reconstructions,
        telemetry.last_frontier_scanned_records,
        telemetry.last_frontier_scanned_bytes,
        telemetry.last_frontier_xid_lock_windows,
        telemetry.last_frontier_reconstructed ? "true" : "false",
        last_attempt_age_json,
        last_completed_age_json,
        last_error_age_json,
        last_error_json.data
    );
    pfree(last_error_json.data);
    return json;
}

