PG_FUNCTION_INFO_V1(ii42_test_query_block_cost);
Datum
ii42_test_query_block_cost(PG_FUNCTION_ARGS)
{
    Oid index_oid = PG_GETARG_OID(0);
    ArrayType *query_array = PG_GETARG_ARRAYTYPE_P(1);
    ArrayType *weight_array = PG_GETARG_ARRAYTYPE_P(2);
    int32 requested_k = PG_GETARG_INT32(3);
    ii42_am_test_query_block_cost_cleanup *cleanup;
    ii42_page_query_cost_audit audit;
    ii42_am_meta_page meta;
    ii42_segment_read_root root;
    size_t query_len = 0;
    StringInfoData json;
    Datum result = (Datum) 0;

    if (!superuser())
    {
        ereport(
            ERROR,
            (
                errcode(ERRCODE_INSUFFICIENT_PRIVILEGE),
                errmsg("ii42 block-cost probe is superuser-only")
            )
        );
    }
    if (requested_k <= 0)
    {
        ereport(ERROR, (errmsg("invalid ii42 block-cost request")));
    }
    cleanup = palloc0(sizeof(*cleanup));
    ii42_segment_query_context_init(&cleanup->context);
    ii42_init_reloptions();

    PG_TRY();
    {
        ii42_status status;

        cleanup->index_relation = index_open(index_oid, AccessShareLock);
        ii42_am_require_index_relation(cleanup->index_relation);
        ii42_am_read_meta(cleanup->index_relation, &meta);
        if (!ii42_am_meta_uses_convergent_segment_storage(&meta) ||
            ii42_am_segment_read_root_from_meta(&meta, &root) != II42_OK)
        {
            ereport(
                ERROR,
                (errmsg("block-cost probe requires v3 storage"))
            );
        }
        ii42_segment_pages_load_query_context(
            cleanup->index_relation,
            &root,
            &cleanup->context
        );
        ii42_am_read_weighted_query_arrays(
            query_array,
            weight_array,
            &cleanup->query_ids,
            &cleanup->query_weights,
            &query_len
        );
        status = ii42_page_query_cost_audit_run(
            cleanup->index_relation,
            &cleanup->context,
            cleanup->query_ids,
            cleanup->query_weights,
            query_len,
            (size_t) requested_k,
            &audit
        );
        if (status != II42_OK)
        {
            ereport(
                ERROR,
                (
                    errmsg("failed to audit ii42 block cost"),
                    errdetail("Audit failed: %s.", ii42_strerror(status))
                )
            );
        }

        initStringInfo(&json);
        appendStringInfo(
            &json,
            "{\"query_terms\":%u,\"query_runs\":%u,"
            "\"query_postings\":\"" UINT64_FORMAT "\","
            "\"document_slots\":\"" UINT64_FORMAT "\","
            "\"k\":%d,\"kth_score\":%.9g,\"levels\":[",
            audit.query_term_count,
            audit.query_run_count,
            audit.query_postings,
            audit.document_slot_count,
            requested_k,
            (double) audit.kth_score
        );
        for (size_t level_index = 0;
             level_index < II42_PAGE_QUERY_COST_BASE_LEVEL_COUNT;
             level_index++)
        {
            const ii42_page_query_cost_level *level =
                &audit.levels[level_index];
            double posting_fraction = level->total_postings == 0
                ? 0.0
                : (double) level->competitive_postings /
                    (double) level->total_postings;
            double document_fraction = audit.document_slot_count == 0
                ? 0.0
                : (double) level->competitive_document_slots /
                    (double) audit.document_slot_count;

            if (level_index > 0)
            {
                appendStringInfoChar(&json, ',');
            }
            appendStringInfo(
                &json,
                "{\"block_shift\":%u,\"block_size\":%llu,"
                "\"block_count\":\"" UINT64_FORMAT "\","
                "\"touched_term_blocks\":\"" UINT64_FORMAT "\","
                "\"bound_bytes\":\"" UINT64_FORMAT "\","
                "\"total_postings\":\"" UINT64_FORMAT "\","
                "\"competitive_blocks\":\"" UINT64_FORMAT "\","
                "\"competitive_postings\":\"" UINT64_FORMAT "\","
                "\"competitive_document_slots\":\""
                    UINT64_FORMAT "\","
                "\"posting_fraction\":%.9g,"
                "\"document_fraction\":%.9g}",
                level->block_shift,
                (unsigned long long) (
                    UINT64_C(1) << level->block_shift
                ),
                level->block_count,
                level->touched_term_blocks,
                level->bound_bytes,
                level->total_postings,
                level->competitive_blocks,
                level->competitive_postings,
                level->competitive_document_slots,
                posting_fraction,
                document_fraction
            );
        }
        appendStringInfo(
            &json,
            "],\"hierarchy\":{"
            "\"nodes_read\":\"" UINT64_FORMAT "\","
            "\"sparse_term_hits\":\"" UINT64_FORMAT "\","
            "\"dense_term_probes\":\"" UINT64_FORMAT "\","
            "\"leaf_blocks\":\"" UINT64_FORMAT "\","
            "\"leaf_postings\":\"" UINT64_FORMAT "\","
            "\"optimal_sparse\":{"
            "\"nodes_read\":\"" UINT64_FORMAT "\","
            "\"term_hits\":\"" UINT64_FORMAT "\","
            "\"level_mask\":%u},"
            "\"optimal_dense\":{"
            "\"nodes_read\":\"" UINT64_FORMAT "\","
            "\"term_probes\":\"" UINT64_FORMAT "\","
            "\"level_mask\":%u}},"
            "\"hierarchy_levels\":[",
            audit.hierarchy_nodes_read,
            audit.hierarchy_sparse_term_hits,
            audit.hierarchy_dense_term_probes,
            audit.hierarchy_leaf_blocks,
            audit.hierarchy_leaf_postings,
            audit.optimal_sparse_plan.nodes_read,
            audit.optimal_sparse_plan.sparse_term_hits,
            (unsigned int) audit.optimal_sparse_plan.level_mask,
            audit.optimal_dense_plan.nodes_read,
            audit.optimal_dense_plan.dense_term_probes,
            (unsigned int) audit.optimal_dense_plan.level_mask
        );
        for (size_t level_index = 0;
             level_index < II42_PAGE_QUERY_COST_LEVEL_COUNT;
             level_index++)
        {
            const ii42_page_query_cost_level *level =
                &audit.levels[level_index];

            if (level_index > 0)
            {
                appendStringInfoChar(&json, ',');
            }
            appendStringInfo(
                &json,
                "{\"block_shift\":%u,\"block_size\":%llu,"
                "\"block_count\":\"" UINT64_FORMAT "\","
                "\"touched_term_blocks\":\"" UINT64_FORMAT "\","
                "\"competitive_blocks\":\"" UINT64_FORMAT "\"}",
                level->block_shift,
                (unsigned long long) (
                    UINT64_C(1) << level->block_shift
                ),
                level->block_count,
                level->touched_term_blocks,
                level->competitive_blocks
            );
        }
        appendStringInfo(
            &json,
            "],\"essential_term_projection\":{"
            "\"mandatory_terms\":%u,"
            "\"projectable_semantic_terms\":%u,"
            "\"mandatory_touched_b16_blocks\":\"" UINT64_FORMAT "\","
            "\"points\":[",
            audit.mandatory_term_count,
            audit.projectable_semantic_term_count,
            audit.mandatory_touched_b16_blocks
        );
        for (uint32 projection_index = 0;
             projection_index < audit.essential_projection_count;
             projection_index++)
        {
            const ii42_page_query_cost_essential_projection *projection =
                &audit.essential_projections[projection_index];
            double posting_fraction = audit.query_postings == 0
                ? 0.0
                : (double) projection->competitive_postings /
                    (double) audit.query_postings;
            double document_fraction = audit.document_slot_count == 0
                ? 0.0
                : (double) projection->competitive_document_slots /
                    (double) audit.document_slot_count;

            if (projection_index != 0)
            {
                appendStringInfoChar(&json, ',');
            }
            appendStringInfo(
                &json,
                "{\"essential_semantic_terms\":%u,"
                "\"residual_semantic_terms\":%u,"
                "\"residual_global_cap\":%.9g,"
                "\"residual_global_floor\":%.9g,"
                "\"residual_global_absolute_cap\":%.9g,"
                "\"kth_lower_bound\":%.9g,"
                "\"kth_lower_bound_safe\":%s,"
                "\"essential_semantic_super_refs\":\""
                    UINT64_FORMAT "\","
                "\"essential_semantic_refs\":\"" UINT64_FORMAT "\","
                "\"essential_semantic_postings\":\""
                    UINT64_FORMAT "\","
                "\"competitive_blocks\":\"" UINT64_FORMAT "\","
                "\"competitive_postings\":\"" UINT64_FORMAT "\","
                "\"competitive_document_slots\":\""
                    UINT64_FORMAT "\","
                "\"missed_full_competitive_blocks\":\""
                    UINT64_FORMAT "\","
                "\"posting_fraction\":%.9g,"
                "\"document_fraction\":%.9g}",
                projection->essential_semantic_terms,
                projection->residual_semantic_terms,
                (double) projection->residual_global_cap,
                (double) projection->residual_global_floor,
                (double) projection->residual_global_absolute_cap,
                (double) projection->kth_lower_bound,
                projection->kth_lower_bound_safe ? "true" : "false",
                projection->essential_semantic_super_refs,
                projection->essential_semantic_refs,
                projection->essential_semantic_postings,
                projection->competitive_blocks,
                projection->competitive_postings,
                projection->competitive_document_slots,
                projection->missed_full_competitive_blocks,
                posting_fraction,
                document_fraction
            );
        }
        appendStringInfoString(&json, "]}}");
        result = DirectFunctionCall1(
            jsonb_in,
            CStringGetDatum(json.data)
        );
        pfree(json.data);
    }
    PG_FINALLY();
    {
        ii42_am_test_query_block_cost_cleanup_free(cleanup);
        pfree(cleanup);
    }
    PG_END_TRY();
    PG_RETURN_DATUM(result);
}

