static uint64
ii42_am_page_native_memory_estimate(
    const ii42_am_page_native_search_cleanup *cleanup,
    size_t rank_limit,
    size_t wanted_k,
    const ii42_page_query_stats *stats
)
{
    uint64 bytes = sizeof(*cleanup);

#define II42_PAGE_QUERY_ADD_ARRAY(count, type) \
    bytes = ii42_u64_saturating_add( \
        bytes, \
        ii42_u64_saturating_mul((uint64) (count), sizeof(type)) \
    )

    II42_PAGE_QUERY_ADD_ARRAY(
        cleanup->context.manifest.segment_count,
        ii42_segment_descriptor
    );
    II42_PAGE_QUERY_ADD_ARRAY(
        cleanup->context.manifest.retired_range_count,
        ii42_block_range
    );
    II42_PAGE_QUERY_ADD_ARRAY(
        cleanup->projection.term_count,
        ii42_page_query_l0_term_stats
    );
    II42_PAGE_QUERY_ADD_ARRAY(
        cleanup->projection.document_count,
        ii42_page_query_l0_document
    );
    II42_PAGE_QUERY_ADD_ARRAY(
        cleanup->projection.contribution_count,
        ii42_page_query_l0_contribution
    );
    II42_PAGE_QUERY_ADD_ARRAY(rank_limit, uint32_t);
    II42_PAGE_QUERY_ADD_ARRAY(rank_limit, float);
    II42_PAGE_QUERY_ADD_ARRAY(wanted_k, ItemPointerData);
    II42_PAGE_QUERY_ADD_ARRAY(wanted_k, uint32_t);
    II42_PAGE_QUERY_ADD_ARRAY(wanted_k, float);
    II42_PAGE_QUERY_ADD_ARRAY(
        stats->query_run_count,
        ii42_segment_query_run
    );
    II42_PAGE_QUERY_ADD_ARRAY(
        stats->query_run_count,
        ii42_segment_query_block
    );
    if (cleanup->context.page_validation_cache != NULL)
    {
        bytes = ii42_u64_saturating_add(
            bytes,
            sizeof(*cleanup->context.page_validation_cache)
        );
    }
    bytes = ii42_u64_saturating_add(
        bytes,
        stats->materialized_query_bytes
    );
    bytes = ii42_u64_saturating_add(
        bytes,
        stats->term_at_a_time_score_bytes
    );
    bytes = ii42_u64_saturating_add(
        bytes,
        stats->semantic_bmp_query_bytes
    );
    bytes = ii42_u64_saturating_add(
        bytes,
        stats->semantic_accelerator_query_bytes
    );
    if (stats->term_at_a_time_query_path)
    {
        bytes = ii42_u64_saturating_add(
            bytes,
            stats->term_at_a_time_document_length_bytes
        );
        bytes = ii42_u64_saturating_add(
            bytes,
            ii42_u64_saturating_mul(
                II42_SEGMENT_QUERY_POSTING_WINDOW,
                sizeof(uint32) + sizeof(ii42_posting_value)
            )
        );
    }
    bytes = ii42_u64_saturating_add(
        bytes,
        stats->posting_block_metadata_cache_bytes
    );
#undef II42_PAGE_QUERY_ADD_ARRAY
    return bytes;
}

static void
ii42_am_attach_page_native_validation_bitmap(
    Relation index_relation,
    const ii42_am_meta_page *meta,
    ii42_am_page_native_search_cleanup *cleanup
)
{
    ii42_segment_query_context *context;
    ii42_am_preload_reservation reservation;
    ii42_am_preload_reserve_result reserve_result;
    uint64 block_count;
    uint64 word_count;
    Size payload_size;

    if (index_relation == NULL || meta == NULL || cleanup == NULL)
    {
        return;
    }
    context = &cleanup->context;
    block_count = context->root.published_block_high_watermark;
    if (context->page_validation_cache == NULL || block_count == 0)
    {
        return;
    }
    word_count = (block_count + UINT64_C(63)) >> 6;
    if (word_count == 0 ||
        word_count > SIZE_MAX / sizeof(pg_atomic_uint64) ||
        word_count > UINT32_MAX)
    {
        return;
    }
    payload_size = (Size) word_count * sizeof(pg_atomic_uint64);
    if (ii42_am_preload_attach(
            index_relation,
            meta,
            II42_AM_PRELOAD_VALIDATED_PAGES,
            &cleanup->validated_pages_lease))
    {
        if (ii42_am_preload_lease_payload_size(
                &cleanup->validated_pages_lease) == payload_size)
        {
            context->page_validation_cache->shared_block_words =
                ii42_am_preload_lease_mutable_payload(
                    &cleanup->validated_pages_lease
                );
            context->page_validation_cache->shared_block_word_count =
                (uint32) word_count;
            return;
        }
        ii42_am_preload_lease_release(&cleanup->validated_pages_lease);
        ii42_am_preload_retire_exact(
            index_relation,
            meta,
            II42_AM_PRELOAD_VALIDATED_PAGES
        );
    }

    reserve_result = ii42_am_preload_reserve(
        index_relation,
        meta,
        II42_AM_PRELOAD_VALIDATED_PAGES,
        payload_size,
        &reservation
    );
    if (reserve_result != II42_AM_PRELOAD_RESERVE_NEW)
    {
        return;
    }
    for (uint64 word_index = 0; word_index < word_count; word_index++)
    {
        pg_atomic_init_u64(
            &((pg_atomic_uint64 *)
                ii42_am_preload_reservation_payload(
                    &reservation
                ))[word_index],
            0
        );
    }
    if (!ii42_am_preload_reservation_commit(&reservation))
    {
        return;
    }
    if (ii42_am_preload_attach(
            index_relation,
            meta,
            II42_AM_PRELOAD_VALIDATED_PAGES,
            &cleanup->validated_pages_lease))
    {
        context->page_validation_cache->shared_block_words =
            ii42_am_preload_lease_mutable_payload(
                &cleanup->validated_pages_lease
            );
        context->page_validation_cache->shared_block_word_count =
            (uint32) word_count;
    }
}

#define II42_AM_DOCUMENT_LENGTHS_MAGIC UINT32_C(0x49344c4e)
#define II42_AM_DOCUMENT_LENGTHS_VERSION UINT32_C(1)

typedef struct ii42_am_document_lengths_header
{
    uint32 magic;
    uint32 version;
    ii42_am_query_metadata_authority authority;
    uint64 document_slot_count;
} ii42_am_document_lengths_header;

typedef struct ii42_am_document_length_build
{
    uint32 *lengths;
    uint64 document_slot_count;
    uint64 next_document_slot;
    bool valid;
} ii42_am_document_length_build;

static void
ii42_am_collect_document_length(
    void *context,
    const ii42_document_cow_record *document
)
{
    ii42_am_document_length_build *build = context;

    if (build == NULL || document == NULL || !build->valid)
    {
        return;
    }
    if (document->version.document_slot < build->next_document_slot)
    {
        build->valid = false;
        return;
    }
    if (document->version.document_slot >= build->document_slot_count)
    {
        return;
    }
    if (document->version.document_slot != build->next_document_slot)
    {
        build->valid = false;
        return;
    }
    build->lengths[build->next_document_slot] =
        document->version.document_length;
    build->next_document_slot++;
}

static void
ii42_am_attach_page_native_document_lengths(
    Relation index_relation,
    const ii42_am_meta_page *meta,
    ii42_segment_query_context *context,
    bool build_if_missing,
    ii42_am_preload_lease *lease
)
{
    ii42_am_preload_reservation reservation = {0};
    ii42_am_preload_reserve_result reserve_result;
    ii42_am_query_metadata_authority authority;
    uint64 document_slot_count;
    Size payload_size;
    bool complete = false;

    if (index_relation == NULL || meta == NULL || context == NULL ||
        lease == NULL)
    {
        return;
    }
    ii42_am_query_metadata_authority_from_context(context, &authority);
    document_slot_count = context->manifest.document_slot_count;
    if ((authority.flags & II42_AM_QUERY_METADATA_ACCELERATOR) != 0)
    {
        ii42_semantic_accelerator_directory directory;

        ii42_semantic_accelerator_directory_init(&directory);
        PG_TRY();
        {
            ii42_segment_pages_load_semantic_accelerator_directory(
                index_relation,
                &context->root,
                &context->manifest,
                &directory
            );
            document_slot_count = directory.document_count;
        }
        PG_FINALLY();
        {
            ii42_semantic_accelerator_directory_free(&directory);
        }
        PG_END_TRY();
    }
    if (document_slot_count == 0 ||
        document_slot_count >
            (SIZE_MAX - sizeof(ii42_am_document_lengths_header)) /
                sizeof(uint32))
    {
        return;
    }
    payload_size = sizeof(ii42_am_document_lengths_header) +
        (Size) document_slot_count * sizeof(uint32);
    if (ii42_am_preload_attach(
            index_relation,
            meta,
            II42_AM_PRELOAD_DOCUMENT_LENGTHS,
            lease))
    {
        const char *payload = ii42_am_preload_lease_payload(lease);
        const ii42_am_document_lengths_header *header =
            (const ii42_am_document_lengths_header *) payload;

        if (ii42_am_preload_lease_payload_size(lease) == payload_size &&
            header->magic == II42_AM_DOCUMENT_LENGTHS_MAGIC &&
            header->version == II42_AM_DOCUMENT_LENGTHS_VERSION &&
            header->document_slot_count == document_slot_count &&
            ii42_am_query_metadata_authority_matches(
                &header->authority,
                &authority))
        {
            context->resident_document_lengths =
                (const uint32 *) (payload + sizeof(*header));
            context->resident_document_length_count = document_slot_count;
            return;
        }
        ii42_am_preload_lease_release(lease);
        ii42_am_preload_retire_exact(
            index_relation,
            meta,
            II42_AM_PRELOAD_DOCUMENT_LENGTHS
        );
    }
    if (!build_if_missing)
    {
        return;
    }

    reserve_result = ii42_am_preload_reserve(
        index_relation,
        meta,
        II42_AM_PRELOAD_DOCUMENT_LENGTHS,
        payload_size,
        &reservation
    );
    if (reserve_result != II42_AM_PRELOAD_RESERVE_NEW)
    {
        return;
    }
    PG_TRY();
    {
        char *payload = ii42_am_preload_reservation_payload(&reservation);
        ii42_am_document_lengths_header *header =
            (ii42_am_document_lengths_header *) payload;
        uint32 *lengths =
            (uint32 *) (payload + sizeof(*header));

        complete = document_slot_count ==
                context->manifest.document_slot_count &&
            ii42_segment_pages_load_query_document_lengths(
                index_relation,
                context,
                lengths
            );
        if (!complete)
        {
            ii42_segment_query_document_reader reader;
            ii42_am_document_length_build build;

            memset(&reader, 0, sizeof(reader));
            memset(&build, 0, sizeof(build));
            build.lengths = lengths;
            build.document_slot_count = document_slot_count;
            build.valid = true;
            ii42_segment_pages_visit_query_document_records(
                index_relation,
                context,
                &reader,
                ii42_am_collect_document_length,
                &build
            );
            complete = build.valid &&
                build.next_document_slot == document_slot_count;
        }
        if (complete)
        {
            header->magic = II42_AM_DOCUMENT_LENGTHS_MAGIC;
            header->version = II42_AM_DOCUMENT_LENGTHS_VERSION;
            header->authority = authority;
            header->document_slot_count = document_slot_count;
        }
    }
    PG_CATCH();
    {
        ii42_am_preload_reservation_abort(&reservation);
        PG_RE_THROW();
    }
    PG_END_TRY();
    if (!complete)
    {
        ii42_am_preload_reservation_abort(&reservation);
        return;
    }
    if (!ii42_am_preload_reservation_commit(&reservation))
    {
        return;
    }
    ii42_am_attach_page_native_document_lengths(
        index_relation,
        meta,
        context,
        false,
        lease
    );
}

static bool
ii42_am_prewarm_page_native_document_lengths(
    Relation index_relation,
    const ii42_am_meta_page *meta,
    const ii42_segment_read_root *root,
    bool *loading_out
)
{
    ii42_segment_query_context context;
    ii42_am_preload_lease lease = {0};
    bool loading = false;
    bool resident = false;
    bool ready = false;

    if (loading_out != NULL)
    {
        *loading_out = false;
    }
    if (index_relation == NULL || meta == NULL || root == NULL)
    {
        return false;
    }
    ii42_segment_query_context_init(&context);
    PG_TRY();
    {
        ii42_segment_pages_load_query_context(
            index_relation,
            root,
            &context
        );
        ii42_am_attach_page_native_document_lengths(
            index_relation,
            meta,
            &context,
            true,
            &lease
        );
        ready = context.resident_document_lengths != NULL &&
            context.resident_document_length_count > 0;
        if (!ready)
        {
            ii42_am_preload_exact_state(
                index_relation,
                meta,
                II42_AM_PRELOAD_DOCUMENT_LENGTHS,
                &resident,
                &loading
            );
            if (resident)
            {
                ii42_am_attach_page_native_document_lengths(
                    index_relation,
                    meta,
                    &context,
                    false,
                    &lease
                );
                ready = context.resident_document_lengths != NULL &&
                    context.resident_document_length_count > 0;
            }
        }
    }
    PG_FINALLY();
    {
        ii42_am_preload_lease_release(&lease);
        ii42_segment_query_context_free(&context);
    }
    PG_END_TRY();
    if (loading_out != NULL)
    {
        *loading_out = loading && !ready;
    }
    return ready;
}

static void
ii42_am_page_native_search_cleanup_free(
    ii42_am_page_native_search_cleanup *cleanup
)
{
    if (cleanup == NULL)
    {
        return;
    }
    ii42_am_preload_lease_release(&cleanup->validated_pages_lease);
    ii42_am_preload_lease_release(&cleanup->document_lengths_lease);
    ii42_am_preload_lease_release(&cleanup->document_tid_lookup_lease);
    ii42_am_resident_fold_view_release(
        &cleanup->tid_filter.resident_view
    );
    if (cleanup->visibility_started)
    {
        ii42_am_visibility_end(&cleanup->visibility);
        cleanup->visibility_started = false;
    }
    if (cleanup->resolved_query_ids != NULL)
    {
        pfree(cleanup->resolved_query_ids);
        cleanup->resolved_query_ids = NULL;
    }
    if (cleanup->expanded_query_ids != NULL)
    {
        pfree(cleanup->expanded_query_ids);
        cleanup->expanded_query_ids = NULL;
    }
    if (cleanup->expanded_query_tokens != NULL)
    {
        pfree(cleanup->expanded_query_tokens);
        cleanup->expanded_query_tokens = NULL;
    }
    if (cleanup->l0_prefix_terms != NULL)
    {
        for (size_t term_index = 0;
             term_index < cleanup->l0_prefix_term_count;
             term_index++)
        {
            pfree(cleanup->l0_prefix_terms[term_index].token);
        }
        pfree(cleanup->l0_prefix_terms);
        cleanup->l0_prefix_terms = NULL;
        cleanup->l0_prefix_term_count = 0;
    }
    if (cleanup->allowed_document_bitmap != NULL)
    {
        pfree(cleanup->allowed_document_bitmap);
        cleanup->allowed_document_bitmap = NULL;
        cleanup->allowed_document_bitmap_bytes = 0;
    }
    if (cleanup->tid_filter.hash_keys != NULL)
    {
        pfree(cleanup->tid_filter.hash_keys);
        cleanup->tid_filter.hash_keys = NULL;
        cleanup->tid_filter.hash_capacity = 0;
    }
    if (cleanup->tid_filter.durable_lookup_bytes != NULL)
    {
        pfree(cleanup->tid_filter.durable_lookup_bytes);
        cleanup->tid_filter.durable_lookup_bytes = NULL;
        cleanup->tid_filter.durable_lookup_size = 0;
        memset(&cleanup->tid_filter.durable_lookup, 0,
            sizeof(cleanup->tid_filter.durable_lookup));
    }
    ii42_topk_result_free(&cleanup->ranked);
    ii42_page_query_l0_projection_free(&cleanup->projection);
    ii42_segment_query_context_free(&cleanup->context);
    pfree(cleanup);
}

static bool
ii42_am_try_shared_resident_fold_search(
    Relation indexRelation,
    Relation heapRelation,
    const ii42_am_meta_page *meta,
    const ii42_segment_read_root *root,
    const uint32_t *query_ids,
    const float *query_weights,
    const char *const *query_tokens,
    const bool *query_prefixes,
    size_t query_len,
    bool numeric_source,
    size_t requested_k,
    Snapshot visibility_snapshot,
    ii42_query_state *state_out,
    ii42_am_page_native_search_trace *trace_out
)
{
    ii42_am_resident_fold_view view;
    ii42_am_visibility_ctx visibility;
    ii42_topk_result ranked = {0};
    ii42_blockmax_stats total_stats = {0};
    uint32_t *resolved_query_ids = NULL;
    const uint32_t *effective_query_ids = query_ids;
    const ItemPointerData *document_tids;
    size_t document_count;
    size_t wanted_k;
    size_t rank_limit;
    size_t rank_max;
    size_t visible = 0;
    uint32 visibility_rank_attempts = 0;
    bool visibility_started = false;
    bool scoring_failed = false;
    bool success = false;

    ii42_am_resident_fold_view_init(&view);
    memset(&visibility, 0, sizeof(visibility));
    if (indexRelation == NULL || heapRelation == NULL || meta == NULL ||
        root == NULL || state_out == NULL || trace_out == NULL ||
        query_len == 0 ||
        root->active_l0.record_count != 0 ||
        root->pending_l0.record_count != 0)
    {
        return false;
    }
    for (size_t query_index = 0; query_index < query_len; query_index++)
    {
        if (query_prefixes != NULL && query_prefixes[query_index])
        {
            return false;
        }
    }
    if ((numeric_source && query_ids == NULL) ||
        (!numeric_source && query_ids == NULL && query_tokens == NULL) ||
        !ii42_am_resident_fold_attach(indexRelation, meta, &view) ||
        ii42_am_resident_fold_root_id(&view) != root->root_id)
    {
        ii42_am_resident_fold_view_release(&view);
        return false;
    }
    if (!numeric_source && effective_query_ids == NULL)
    {
        resolved_query_ids = palloc(
            sizeof(*resolved_query_ids) * query_len
        );
        for (size_t query_index = 0; query_index < query_len; query_index++)
        {
            uint32 term_id = UINT32_MAX;

            if (query_tokens[query_index] == NULL ||
                !ii42_am_resident_fold_lookup_token(
                    &view,
                    query_tokens[query_index],
                    &term_id))
            {
                term_id = UINT32_MAX;
            }
            resolved_query_ids[query_index] = term_id;
        }
        effective_query_ids = resolved_query_ids;
    }
    document_count = ii42_am_resident_fold_document_count(&view);
    rank_max = document_count;
    wanted_k = Min(requested_k, rank_max);
    document_tids = ii42_am_resident_fold_document_tids(&view);
    if (rank_max > 0 && document_tids == NULL)
    {
        goto resident_done;
    }

    PG_TRY();
    {
        if (wanted_k > 0)
        {
            ii42_am_visibility_begin_with_snapshot(
                heapRelation,
                visibility_snapshot != NULL
                    ? visibility_snapshot
                    : GetActiveSnapshot(),
                &visibility
            );
            visibility_started = true;
            ii42_am_init_search_result(wanted_k, state_out);
            rank_limit = Min(wanted_k, rank_max);
            while (rank_limit > 0)
            {
                ii42_blockmax_stats attempt_stats = {0};
                ii42_status status;

                visibility_rank_attempts = ii42_u32_saturating_add(
                    visibility_rank_attempts,
                    1
                );
                status = ii42_am_resident_fold_topk(
                    &view,
                    effective_query_ids,
                    query_weights,
                    query_len,
                    rank_limit,
                    &ranked,
                    &attempt_stats
                );
                if (status != II42_OK)
                {
                    scoring_failed = true;
                    break;
                }
                total_stats.blocks_considered = ii42_u64_saturating_add(
                    total_stats.blocks_considered,
                    attempt_stats.blocks_considered
                );
                total_stats.blocks_scored = ii42_u64_saturating_add(
                    total_stats.blocks_scored,
                    attempt_stats.blocks_scored
                );
                total_stats.blocks_skipped = ii42_u64_saturating_add(
                    total_stats.blocks_skipped,
                    attempt_stats.blocks_skipped
                );
                total_stats.postings_scored = ii42_u64_saturating_add(
                    total_stats.postings_scored,
                    attempt_stats.postings_scored
                );
                ii42_am_test_error_if_enabled(
                    "ii42.test_search_error_after_rank",
                    "resident fold search result construction"
                );
                visible = 0;
                for (size_t rank = 0;
                     rank < ranked.len && visible < wanted_k;
                     rank++)
                {
                    uint32 doc_id = ranked.doc_ids[rank];
                    ItemPointerData visible_tid;

                    if (doc_id >= document_count ||
                        !ii42_am_tid_visible_as(
                            &visibility,
                            &document_tids[doc_id],
                            &visible_tid))
                    {
                        continue;
                    }
                    ii42_am_append_search_hit(
                        state_out,
                        visible,
                        &visible_tid,
                        doc_id,
                        ranked.scores[rank]
                    );
                    visible++;
                }
                state_out->topk.len = visible;
                if (visible >= wanted_k || rank_limit >= rank_max ||
                    ranked.len == 0)
                {
                    break;
                }
                ii42_topk_result_free(&ranked);
                rank_limit = ii42_am_next_visibility_rank_limit(
                    rank_limit,
                    wanted_k,
                    rank_max
                );
            }
        }
        success = !scoring_failed;
    }
    PG_CATCH();
    {
        if (visibility_started)
        {
            ii42_am_visibility_end(&visibility);
        }
        ii42_topk_result_free(&ranked);
        ii42_am_resident_fold_view_release(&view);
        if (resolved_query_ids != NULL)
        {
            pfree(resolved_query_ids);
        }
        ii42_am_search_state_reset(state_out);
        PG_RE_THROW();
    }
    PG_END_TRY();

resident_done:
    if (visibility_started)
    {
        ii42_am_visibility_end(&visibility);
    }
    ii42_topk_result_free(&ranked);
    ii42_am_resident_fold_view_release(&view);
    if (resolved_query_ids != NULL)
    {
        pfree(resolved_query_ids);
    }
    if (!success)
    {
        ii42_am_search_state_reset(state_out);
        return false;
    }
    memset(trace_out, 0, sizeof(*trace_out));
    trace_out->visible_document_count = rank_max;
    trace_out->query.query_term_count = query_len;
    trace_out->query.visibility_rank_attempts = visibility_rank_attempts;
    trace_out->query.shared_resident_fold_query_path = true;
    trace_out->query.blocks_considered = total_stats.blocks_considered;
    trace_out->query.blocks_scored = total_stats.blocks_scored;
    trace_out->query.blocks_skipped = total_stats.blocks_skipped;
    trace_out->query.postings_examined = total_stats.postings_scored;
    trace_out->query.documents_examined = total_stats.postings_scored;
    trace_out->query.positive_document_count = visible;
    trace_out->query.positive_topk_complete = true;
    trace_out->query.topk_complete = true;
    trace_out->memory_bytes =
        (uint64) wanted_k *
        (sizeof(ItemPointerData) + sizeof(uint32_t) + sizeof(float));
    return true;
}

static bool
ii42_am_try_shared_hot_fold_search(
    Relation indexRelation,
    Relation heapRelation,
    const ii42_am_meta_page *meta,
    const ii42_segment_read_root *root,
    uint32 term_id,
    size_t requested_k,
    Snapshot visibility_snapshot,
    ii42_query_state *state_out,
    ii42_am_page_native_search_trace *trace_out
)
{
    ii42_am_hot_fold_view view;
    const ii42_am_hot_fold_term *term;
    const ii42_am_hot_fold_entry *term_entries;
    ii42_am_visibility_ctx visibility;
    size_t wanted_k;
    size_t visible = 0;
    uint64 examined = 0;
    uint64 positive_document_count = 0;
    bool visibility_started = false;
    bool success = false;

    ii42_am_hot_fold_view_init(&view);
    memset(&visibility, 0, sizeof(visibility));
    if (indexRelation == NULL || heapRelation == NULL || meta == NULL ||
        root == NULL || state_out == NULL || trace_out == NULL ||
        root->active_l0.record_count != 0 ||
        root->pending_l0.record_count != 0 ||
        !ii42_am_hot_fold_attach(indexRelation, meta, &view))
    {
        return false;
    }
    term = ii42_am_hot_fold_find_term(&view, term_id);
    term_entries = ii42_am_hot_fold_term_entries(&view, term);
    wanted_k = Min(requested_k, (size_t) meta->num_docs);
    if (term == NULL || term_entries == NULL ||
        term->entry_count < wanted_k)
    {
        ii42_am_hot_fold_view_release(&view);
        return false;
    }
    positive_document_count = term->entry_count;

    PG_TRY();
    {
        if (wanted_k > 0)
        {
            ii42_am_init_search_result(wanted_k, state_out);
            ii42_am_visibility_begin_with_snapshot(
                heapRelation,
                visibility_snapshot != NULL
                    ? visibility_snapshot
                    : GetActiveSnapshot(),
                &visibility
            );
            visibility_started = true;
            for (uint64 entry_index = 0;
                 entry_index < term->entry_count &&
                     visible < wanted_k;
                 entry_index++)
            {
                const ii42_am_hot_fold_entry *entry =
                    &term_entries[entry_index];
                ItemPointerData visible_tid;

                examined++;
                if (!ii42_am_tid_visible_as(
                        &visibility,
                        &entry->tid,
                        &visible_tid))
                {
                    continue;
                }
                ii42_am_append_search_hit(
                    state_out,
                    visible,
                    &visible_tid,
                    entry->document_slot,
                    entry->score
                );
                visible++;
            }
            state_out->topk.len = visible;
        }
        success = visible == wanted_k;
    }
    PG_CATCH();
    {
        if (visibility_started)
        {
            ii42_am_visibility_end(&visibility);
        }
        ii42_am_hot_fold_view_release(&view);
        ii42_am_search_state_reset(state_out);
        PG_RE_THROW();
    }
    PG_END_TRY();
    if (visibility_started)
    {
        ii42_am_visibility_end(&visibility);
    }
    ii42_am_hot_fold_view_release(&view);
    if (!success)
    {
        ii42_am_search_state_reset(state_out);
        return false;
    }
    memset(trace_out, 0, sizeof(*trace_out));
    trace_out->visible_document_count = meta->num_docs;
    trace_out->query.postings_examined = examined;
    trace_out->query.documents_examined = examined;
    trace_out->query.positive_document_count = positive_document_count;
    trace_out->query.query_term_count = 1;
    trace_out->query.query_run_count = 1;
    trace_out->query.positive_topk_complete = true;
    trace_out->query.topk_complete = true;
    trace_out->memory_bytes =
        (uint64) wanted_k *
        (sizeof(ItemPointerData) + sizeof(uint32_t) + sizeof(float));
    return true;
}

static void
ii42_am_prepare_page_native_filtered_search_state_at_root(
    Relation indexRelation,
    Relation heapRelation,
    Oid expected_source_type,
    const uint32_t *query_ids,
    const float *query_weights,
    const char *const *query_tokens,
    const bool *query_prefixes,
    const bool *query_prefix_expanded,
    size_t query_len,
    bool numeric_source,
    size_t requested_k,
    bool ranked_prefix_already_attempted,
    const ii42_page_query_filter *filter,
    const uint64 *allowed_tid_keys,
    size_t allowed_tid_count,
    Snapshot visibility_snapshot,
    const ii42_segment_read_root *fixed_root,
    ii42_segment_read_root *used_root_out,
    ii42_query_state *state_out,
    ii42_am_page_native_search_trace *trace_out
)
{
    ii42_am_page_native_search_cleanup *cleanup;
    ii42_am_payload_health_state health;
    ii42_am_meta_page meta;
    ii42_segment_read_root root;
    ii42_page_query_l0_input l0_input;
    ii42_page_query_stats total_stats;
    const uint32_t *effective_query_ids;
    const char *const *effective_query_tokens;
    const bool *effective_query_prefixes;
    const ii42_page_query_filter *effective_filter = filter;
    ii42_page_query_filter effective_filter_copy;
    size_t effective_query_len;
    uint64 visible_document_count;
    size_t rank_max;
    size_t rank_limit;
    size_t wanted_k;
    size_t visible = 0;
    ii42_status status;

    if (indexRelation == NULL || heapRelation == NULL || state_out == NULL ||
        trace_out == NULL ||
        (query_len > 0 && numeric_source && query_ids == NULL) ||
        (query_len > 0 && !numeric_source && query_tokens == NULL))
    {
        ereport(ERROR, (errmsg("invalid ii42 page-native search request")));
    }
    memset(state_out, 0, sizeof(*state_out));
    memset(trace_out, 0, sizeof(*trace_out));
    memset(&total_stats, 0, sizeof(total_stats));
    memset(&l0_input, 0, sizeof(l0_input));

    if (ii42_am_sae_enabled(indexRelation))
    {
        ii42_unified_require_shared_runtime();
    }
    if (fixed_root == NULL)
    {
        ii42_am_read_meta(indexRelation, &meta);
        if (!ii42_am_meta_uses_convergent_segment_storage(&meta) ||
            meta.source_type != expected_source_type)
        {
            ereport(
                ERROR,
                (errmsg("ii42 page-native query contract changed"))
            );
        }
        if ((meta.flags & II42_AM_FLAG_STALE) != 0)
        {
            ereport(
                NOTICE,
                (
                    errmsg("ii42 index is stale"),
                    errhint(
                        "Run ii42_index_maintain or REINDEX INDEX to "
                        "refresh it."
                    )
                )
            );
        }
        ii42_am_payload_health(indexRelation, &meta, &health);
        if (health.corrupt ||
            (meta.flags & II42_AM_FLAG_REBUILD_REQUIRED) != 0)
        {
            ereport(
                ERROR,
                (
                    errmsg("invalid ii42 convergent segment payload"),
                    errdetail("Validation failed: %s.", health.reason),
                    errhint("REINDEX the relation to rebuild the index.")
                )
            );
        }
        status = ii42_am_segment_read_root_from_meta(&meta, &root);
    }
    else
    {
        root = *fixed_root;
        status = ii42_segment_read_root_validate(&root);
    }
    if (status != II42_OK)
    {
        ereport(
            ERROR,
            (
                errmsg("invalid ii42 convergent segment root"),
                errdetail("Validation failed: %s.", ii42_strerror(status))
            )
        );
    }
    if (used_root_out != NULL)
    {
        *used_root_out = root;
    }
    ii42_am_test_pause_ms(
        "ii42.test_convergent_root_snapshot_pause_ms",
        "ii42 convergent page-native root snapshot"
    );
    if (filter == NULL && allowed_tid_keys == NULL &&
        fixed_root == NULL && numeric_source &&
        query_weights == NULL && query_len == 1 &&
        query_ids[0] != UINT32_MAX &&
        ii42_am_try_shared_hot_fold_search(
            indexRelation,
            heapRelation,
            &meta,
            &root,
            query_ids[0],
            requested_k,
            visibility_snapshot,
            state_out,
            trace_out
        ))
    {
        return;
    }
    if (filter == NULL && allowed_tid_keys == NULL &&
        fixed_root == NULL &&
        !ii42_am_semantic_accelerator_query_preferred(
            indexRelation,
            &root,
            NULL,
            NULL) &&
        ii42_am_try_shared_resident_fold_search(
            indexRelation,
            heapRelation,
            &meta,
            &root,
            query_ids,
            query_weights,
            query_tokens,
            query_prefixes,
            query_len,
            numeric_source,
            requested_k,
            visibility_snapshot,
            state_out,
            trace_out
        ))
    {
        return;
    }

    cleanup = palloc0(sizeof(*cleanup));
    cleanup->index_relation = indexRelation;
    ii42_segment_query_context_init(&cleanup->context);
    ii42_page_query_l0_projection_init(&cleanup->projection);
    ii42_am_resident_fold_view_init(&cleanup->tid_filter.resident_view);
    PG_TRY();
    {
        ii42_segment_pages_load_query_context(
            indexRelation,
            &root,
            &cleanup->context
        );
        ii42_am_require_segment_manifest_runtime_contract(
            indexRelation,
            &cleanup->context.manifest
        );
        if (fixed_root == NULL)
        {
            ii42_am_attach_page_native_validation_bitmap(
                indexRelation,
                &meta,
                cleanup
            );
            ii42_am_attach_page_native_document_lengths(
                indexRelation,
                &meta,
                &cleanup->context,
                false,
                &cleanup->document_lengths_lease
            );
        }
        else
        {
            ii42_am_meta_page resident_meta;
            ii42_segment_read_root resident_root;

            /*
             * Predicate resolution pins one immutable root before entering
             * the scorer.  Reuse current-root shared projections when that
             * root is still current; otherwise keep the pinned-root fallback
             * rather than attaching state from a different generation.
             */
            ii42_am_read_meta(indexRelation, &resident_meta);
            if (ii42_am_meta_uses_convergent_segment_storage(
                    &resident_meta) &&
                ii42_am_segment_read_root_from_meta(
                    &resident_meta,
                    &resident_root) == II42_OK &&
                resident_root.root_id == fixed_root->root_id &&
                ii42_segment_object_ref_equal(
                    &resident_root.manifest,
                    &fixed_root->manifest))
            {
                ii42_am_attach_page_native_validation_bitmap(
                    indexRelation,
                    &resident_meta,
                    cleanup
                );
                ii42_am_attach_page_native_document_lengths(
                    indexRelation,
                    &resident_meta,
                    &cleanup->context,
                    false,
                    &cleanup->document_lengths_lease
                );
            }
        }
        effective_query_ids = query_ids;
        effective_query_tokens = query_tokens;
        effective_query_prefixes = query_prefixes;
        effective_query_len = query_len;
        if (!numeric_source && query_len > 0 && query_ids == NULL)
        {
            cleanup->resolved_query_ids = palloc(
                sizeof(*cleanup->resolved_query_ids) * query_len
            );
            for (size_t query_index = 0;
                 query_index < query_len;
                 query_index++)
            {
                uint32 term_id = UINT32_MAX;
                const char *token = query_tokens[query_index];
                bool found = false;

                if (token == NULL)
                {
                    ereport(ERROR, (errmsg("invalid ii42 query token")));
                }
                if (cleanup->context.manifest.vocab_size > 0)
                {
                    found = ii42_segment_pages_lookup_lexicon(
                        indexRelation,
                        &cleanup->context.root,
                        &cleanup->context.manifest,
                        (const uint8 *) token,
                        strlen(token),
                        &term_id
                    );
                }
                if (!found)
                {
                    term_id = UINT32_MAX;
                }
                else if (term_id >= cleanup->context.manifest.vocab_size)
                {
                    ereport(
                        ERROR,
                        (errmsg("invalid ii42 page-native lexical term id"))
                    );
                }
                cleanup->resolved_query_ids[query_index] = term_id;
            }
            effective_query_ids = cleanup->resolved_query_ids;
        }
        if (!numeric_source && query_prefixes != NULL)
        {
            size_t retained_count = 0;
            size_t retained_bytes = 0;
            size_t expanded_index = 0;

            if (query_weights != NULL)
            {
                ereport(
                    ERROR,
                    (errmsg("weighted prefix queries are not supported"))
                );
            }
            for (size_t query_index = 0;
                 query_index < query_len;
                 query_index++)
            {
                if (query_prefixes[query_index])
                {
                    continue;
                }
                retained_count++;
                retained_bytes += strlen(query_tokens[query_index]) + 1;
            }
            ii42_am_collect_page_native_l0_prefix_terms(
                indexRelation,
                &cleanup->context,
                query_tokens,
                query_prefixes,
                query_prefix_expanded,
                query_len,
                II42_AM_PAGE_NATIVE_QUERY_MAX_TERMS - retained_count,
                II42_AM_PAGE_NATIVE_PREFIX_MAX_BYTES - retained_bytes,
                &cleanup->l0_prefix_terms,
                &cleanup->l0_prefix_term_count
            );
            effective_query_len = retained_count +
                cleanup->l0_prefix_term_count;
            if (effective_query_len > 0)
            {
                cleanup->expanded_query_ids = palloc(
                    sizeof(*cleanup->expanded_query_ids) *
                    effective_query_len
                );
                cleanup->expanded_query_tokens = palloc(
                    sizeof(*cleanup->expanded_query_tokens) *
                    effective_query_len
                );
            }
            for (size_t query_index = 0;
                 query_index < query_len;
                 query_index++)
            {
                if (query_prefixes[query_index])
                {
                    continue;
                }
                cleanup->expanded_query_ids[expanded_index] =
                    effective_query_ids[query_index];
                cleanup->expanded_query_tokens[expanded_index] =
                    query_tokens[query_index];
                expanded_index++;
            }
            for (size_t term_index = 0;
                 term_index < cleanup->l0_prefix_term_count;
                 term_index++)
            {
                cleanup->expanded_query_ids[expanded_index] = UINT32_MAX;
                cleanup->expanded_query_tokens[expanded_index] =
                    cleanup->l0_prefix_terms[term_index].token;
                expanded_index++;
            }
            if (expanded_index != effective_query_len)
            {
                ereport(ERROR, (errmsg("invalid ii42 prefix expansion")));
            }
            effective_query_ids = cleanup->expanded_query_ids;
            effective_query_tokens =
                (const char *const *) cleanup->expanded_query_tokens;
            effective_query_prefixes = NULL;
        }
        if (filter == NULL && allowed_tid_keys == NULL &&
            fixed_root == NULL && !numeric_source &&
            query_weights == NULL && query_len == 1 &&
            (query_prefixes == NULL || !query_prefixes[0]) &&
            effective_query_len == 1 &&
            effective_query_ids[0] != UINT32_MAX &&
            ii42_am_try_shared_hot_fold_search(
                indexRelation,
                heapRelation,
                &meta,
                &root,
                effective_query_ids[0],
                requested_k,
                visibility_snapshot,
                state_out,
                trace_out
            ))
        {
            goto page_native_done;
        }
        if (root.pending_l0.record_count > 0 ||
            root.active_l0.record_count > 0)
        {
            l0_input.query_ids = effective_query_ids;
            l0_input.query_tokens = effective_query_tokens;
            l0_input.query_prefixes = effective_query_prefixes;
            l0_input.query_len = effective_query_len;
            l0_input.numeric_source = numeric_source;
            ii42_page_query_build_l0_projection(
                indexRelation,
                &cleanup->context,
                &l0_input,
                ii42_am_page_query_resolve_l0_visibility,
                NULL,
                &cleanup->projection
            );
        }
        if (allowed_tid_keys != NULL)
        {
            uint64 document_slot_count =
                cleanup->context.root.next_document_slot;
            uint64 accelerator_baseline_sequence =
                ii42_segment_manifest_semantic_accelerator_baseline_sequence(
                    &cleanup->context.manifest
                );

            cleanup->tid_filter.lookup_baseline_stale =
                accelerator_baseline_sequence > 0 &&
                accelerator_baseline_sequence <
                    cleanup->context.manifest.max_sequence;

            if (filter != NULL)
            {
                cleanup->tid_filter.scope_bitmap =
                    filter->allowed_document_bitmap;
                cleanup->tid_filter.scope_document_slot_count =
                    filter->document_slot_count;
            }

            /*
             * The lookup follows the serving accelerator authority. A stale
             * baseline match is checked against the current document COW TID;
             * linked-L0 replacements are also suppressed by the projection.
             */
            {
                ii42_am_meta_page resident_meta;

                if (fixed_root == NULL)
                {
                    resident_meta = meta;
                }
                else
                {
                    ii42_am_read_meta(indexRelation, &resident_meta);
                }
                ii42_am_attach_page_native_document_tid_lookup(
                    indexRelation,
                    &resident_meta,
                    &cleanup->context,
                    false,
                    &cleanup->document_tid_lookup_lease,
                    &cleanup->tid_filter.resident_lookup_keys,
                    &cleanup->tid_filter.resident_lookup_document_slots,
                    &cleanup->tid_filter.resident_lookup_count
                );
                if (cleanup->tid_filter.resident_lookup_keys == NULL)
                {
                    bool durable_loaded =
                        ii42_segment_pages_load_semantic_accelerator_tid_lookup(
                        indexRelation,
                        &cleanup->context,
                        &cleanup->tid_filter.durable_lookup_bytes,
                        &cleanup->tid_filter.durable_lookup_size,
                        &cleanup->tid_filter.durable_lookup
                    );

                    if (durable_loaded &&
                        !ii42_am_document_tid_lookup_covers_authority(
                            &cleanup->context,
                            &cleanup->tid_filter.durable_lookup))
                    {
                        pfree(cleanup->tid_filter.durable_lookup_bytes);
                        cleanup->tid_filter.durable_lookup_bytes = NULL;
                        cleanup->tid_filter.durable_lookup_size = 0;
                        memset(
                            &cleanup->tid_filter.durable_lookup,
                            0,
                            sizeof(cleanup->tid_filter.durable_lookup)
                        );
                    }
                }
                if (cleanup->tid_filter.resident_lookup_keys == NULL &&
                    cleanup->tid_filter.durable_lookup.bytes == NULL &&
                    ii42_am_resident_fold_attach(
                        indexRelation,
                        &resident_meta,
                        &cleanup->tid_filter.resident_view) &&
                    ii42_am_resident_fold_root_id(
                        &cleanup->tid_filter.resident_view) == root.root_id &&
                    ii42_am_resident_fold_document_count(
                        &cleanup->tid_filter.resident_view) ==
                        document_slot_count)
                {
                    cleanup->tid_filter.resident_document_tids =
                        ii42_am_resident_fold_document_tids(
                            &cleanup->tid_filter.resident_view
                        );
                    cleanup->tid_filter.resident_document_count =
                        ii42_am_resident_fold_document_count(
                            &cleanup->tid_filter.resident_view
                        );
                }
                else
                {
                    ii42_am_resident_fold_view_release(
                        &cleanup->tid_filter.resident_view
                    );
                }
            }

            cleanup->tid_filter.keys = allowed_tid_keys;
            cleanup->tid_filter.key_count = allowed_tid_count;
            cleanup->tid_filter.document_slot_count = document_slot_count;
            ii42_am_resolve_page_native_tid_filter(
                indexRelation,
                cleanup
            );
            effective_filter = &cleanup->resolved_filter;
        }
        if (effective_filter != NULL && ranked_prefix_already_attempted)
        {
            effective_filter_copy = *effective_filter;
            effective_filter_copy.ranked_prefix_already_attempted = true;
            effective_filter = &effective_filter_copy;
        }
        visible_document_count =
            cleanup->projection.term_count > 0 ||
            cleanup->projection.document_count > 0 ||
            cleanup->projection.visited_record_count > 0
                ? cleanup->projection.visible_document_count
                : cleanup->context.manifest.visible_document_count;
        if (effective_filter == NULL)
        {
            rank_max = visible_document_count > (uint64) SIZE_MAX
                ? SIZE_MAX
                : (size_t) visible_document_count;
        }
        else
        {
            rank_max = effective_filter->allowed_document_count >
                (uint64) SIZE_MAX
                ? SIZE_MAX
                : (size_t) effective_filter->allowed_document_count;
            rank_max = Min(
                rank_max,
                visible_document_count > (uint64) SIZE_MAX
                    ? SIZE_MAX
                    : (size_t) visible_document_count
            );
        }
        wanted_k = Min(requested_k, rank_max);
        trace_out->visible_document_count = (uint64) rank_max;
        trace_out->l0_visited_records =
            cleanup->projection.visited_record_count;
        trace_out->l0_visible_records =
            cleanup->projection.visible_record_count;
        trace_out->l0_document_count = cleanup->projection.document_count;
        trace_out->l0_contribution_count =
            cleanup->projection.contribution_count;
        rank_limit = 0;
        if (wanted_k > 0)
        {
            ii42_am_init_search_result(wanted_k, state_out);
            ii42_am_visibility_begin_with_snapshot(
                heapRelation,
                visibility_snapshot != NULL
                    ? visibility_snapshot
                    : GetActiveSnapshot(),
                &cleanup->visibility
            );
            cleanup->visibility_started = true;
            rank_limit = Min(wanted_k, rank_max);
            while (rank_limit > 0)
            {
                ii42_page_query_stats attempt_stats;

                memset(&attempt_stats, 0, sizeof(attempt_stats));
                ii42_topk_result_free(&cleanup->ranked);
                status = ii42_page_query_topk_filtered(
                    indexRelation,
                    &cleanup->context,
                    cleanup->projection.visited_record_count > 0
                        ? &cleanup->projection
                        : NULL,
                    effective_filter,
                    effective_query_ids,
                    query_weights,
                    effective_query_len,
                    rank_limit,
                    &cleanup->ranked,
                    &attempt_stats
                );
                attempt_stats.visibility_rank_attempts = 1;
                if (status != II42_OK)
                {
                    ereport(
                        ERROR,
                        (
                            errmsg("failed to compute page-native top-k"),
                            errdetail(
                                "Scorer failed: %s; terms=%u runs=%u "
                                "bmp_attempted=%s bmp_super_refs=%llu "
                                "bmp_refs=%llu bmp_records=%llu "
                                "bmp_postings=%llu bmp_fallback=%s "
                                "bmp_path=%s materialized=%s taat=%s "
                                "ordered=%s blocks=%llu/%llu/%llu "
                                "document_blocks=%llu.",
                                ii42_strerror(status),
                                attempt_stats.query_term_count,
                                attempt_stats.query_run_count,
                                attempt_stats.semantic_bmp_attempted
                                    ? "true"
                                    : "false",
                                (unsigned long long)
                                    attempt_stats.
                                        semantic_bmp_super_ref_reads,
                                (unsigned long long)
                                    attempt_stats.semantic_bmp_ref_reads,
                                (unsigned long long)
                                    attempt_stats.semantic_bmp_record_reads,
                                (unsigned long long)
                                    attempt_stats.
                                        semantic_bmp_postings_examined,
                                attempt_stats.semantic_bmp_fallback
                                    ? "true"
                                    : "false",
                                attempt_stats.semantic_bmp_query_path
                                    ? "true"
                                    : "false",
                                attempt_stats.materialized_query_path
                                    ? "true"
                                    : "false",
                                attempt_stats.term_at_a_time_query_path
                                    ? "true"
                                    : "false",
                                attempt_stats.ordered_block_query_path
                                    ? "true"
                                    : "false",
                                (unsigned long long)
                                    attempt_stats.blocks_considered,
                                (unsigned long long)
                                    attempt_stats.blocks_scored,
                                (unsigned long long)
                                    attempt_stats.blocks_skipped,
                                (unsigned long long)
                                    attempt_stats.document_block_reads
                            )
                        )
                    );
                }
                trace_out->final_attempt_query = attempt_stats;
                trace_out->final_attempt_query_valid = true;
                ii42_am_page_native_stats_accumulate(
                    &total_stats,
                    &attempt_stats
                );
                visible = 0;
                ii42_am_test_error_if_enabled(
                    "ii42.test_search_error_after_rank",
                    "page-native search result construction"
                );
                {
                    ItemPointerData *ranked_tids = palloc(
                        sizeof(*ranked_tids) * cleanup->ranked.len
                    );
                    bool *resolved_tids = palloc(
                        sizeof(*resolved_tids) * cleanup->ranked.len
                    );

                    ii42_am_resolve_page_native_ranked_tids(
                        indexRelation,
                        cleanup,
                        cleanup->projection.visited_record_count > 0
                            ? &cleanup->projection
                            : NULL,
                        &cleanup->ranked,
                        ranked_tids,
                        resolved_tids
                    );
                    for (size_t rank = 0;
                         rank < cleanup->ranked.len && visible < wanted_k;
                         rank++)
                    {
                        ItemPointerData visible_tid;
                        uint32 document_slot =
                            cleanup->ranked.doc_ids[rank];

                        if (!resolved_tids[rank] ||
                            !ii42_am_tid_visible_as(
                                &cleanup->visibility,
                                &ranked_tids[rank],
                                &visible_tid))
                        {
                            continue;
                        }
                        ii42_am_append_search_hit(
                            state_out,
                            visible,
                            &visible_tid,
                            document_slot,
                            cleanup->ranked.scores[rank]
                        );
                        visible++;
                    }
                    pfree(resolved_tids);
                    pfree(ranked_tids);
                }
                state_out->topk.len = visible;
                if (visible >= wanted_k || rank_limit >= rank_max)
                {
                    break;
                }
                rank_limit = ii42_am_next_visibility_rank_limit(
                    rank_limit,
                    wanted_k,
                    rank_max
                );
            }
        }
        ii42_am_posting_heat_observe_page_native(
            indexRelation,
            fixed_root == NULL ? &meta : NULL,
            &cleanup->context,
            effective_query_ids,
            effective_query_len,
            &total_stats
        );
        trace_out->query = total_stats;
        trace_out->memory_bytes = ii42_am_page_native_memory_estimate(
            cleanup,
            rank_limit,
            wanted_k,
            &total_stats
        );
        trace_out->memory_bytes = ii42_u64_saturating_add(
            trace_out->memory_bytes,
            cleanup->result_projection_bytes
        );
        if (allowed_tid_keys != NULL)
        {
            trace_out->memory_bytes = ii42_u64_saturating_add(
                trace_out->memory_bytes,
                ii42_u64_saturating_add(
                    (uint64) cleanup->allowed_document_bitmap_bytes,
                    (uint64) allowed_tid_count * sizeof(uint64)
                )
            );
        }
page_native_done:
        if (!trace_out->final_attempt_query_valid)
        {
            trace_out->final_attempt_query = trace_out->query;
            trace_out->final_attempt_query_valid = true;
        }
    }
    PG_CATCH();
    {
        ii42_am_page_native_search_cleanup_free(cleanup);
        ii42_am_search_state_reset(state_out);
        PG_RE_THROW();
    }
    PG_END_TRY();
    ii42_am_page_native_search_cleanup_free(cleanup);
}

static void
ii42_am_prepare_page_native_search_state_at_root(
    Relation indexRelation,
    Relation heapRelation,
    Oid expected_source_type,
    const uint32_t *query_ids,
    const float *query_weights,
    const char *const *query_tokens,
    const bool *query_prefixes,
    const bool *query_prefix_expanded,
    size_t query_len,
    bool numeric_source,
    size_t requested_k,
    Snapshot visibility_snapshot,
    const ii42_segment_read_root *fixed_root,
    ii42_segment_read_root *used_root_out,
    ii42_query_state *state_out,
    ii42_am_page_native_search_trace *trace_out
)
{
    ii42_am_prepare_page_native_filtered_search_state_at_root(
        indexRelation,
        heapRelation,
        expected_source_type,
        query_ids,
        query_weights,
        query_tokens,
        query_prefixes,
        query_prefix_expanded,
        query_len,
        numeric_source,
        requested_k,
        false,
        NULL,
        NULL,
        0,
        visibility_snapshot,
        fixed_root,
        used_root_out,
        state_out,
        trace_out
    );
}

static void
ii42_am_prepare_page_native_search_state(
    Relation indexRelation,
    Relation heapRelation,
    Oid expected_source_type,
    const uint32_t *query_ids,
    const float *query_weights,
    const char *const *query_tokens,
    size_t query_len,
    bool numeric_source,
    size_t requested_k,
    ii42_query_state *state_out,
    ii42_am_page_native_search_trace *trace_out
)
{
    ii42_am_prepare_page_native_search_state_at_root(
        indexRelation,
        heapRelation,
        expected_source_type,
        query_ids,
        query_weights,
        query_tokens,
        NULL,
        NULL,
        query_len,
        numeric_source,
        requested_k,
        NULL,
        NULL,
        NULL,
        state_out,
        trace_out
    );
}

#define II42_AM_FILTER_PREFIX_MIN_K ((size_t) 64)
#define II42_AM_FILTER_PREFIX_FIRST_MAX_K ((size_t) 128)
#define II42_AM_FILTER_PREFIX_MAX_K ((size_t) 1024)
#define II42_AM_FILTER_PREFIX_MIN_CORPUS_FACTOR UINT64_C(8)
#define II42_AM_FILTER_RESOLVE_MAX_ROWS UINT64_C(65536)
#define II42_AM_STRUCTURED_SCOPE_OVERFETCH_MULTIPLIER ((size_t) 4)

static bool
ii42_am_filter_prefix_has_physical_leverage(
    const ii42_segment_read_root *root
)
{
    uint64 candidate_multiplier = (uint64) Max(
        ii42_semantic_accelerator_candidate_multiplier,
        1
    );
    uint64 first_probe_candidate_budget;
    uint64 minimum_documents;

    if (candidate_multiplier >
        UINT64_MAX / (uint64) II42_AM_FILTER_PREFIX_FIRST_MAX_K)
    {
        return false;
    }
    first_probe_candidate_budget =
        (uint64) II42_AM_FILTER_PREFIX_FIRST_MAX_K *
        candidate_multiplier;
    if (first_probe_candidate_budget >
        UINT64_MAX / II42_AM_FILTER_PREFIX_MIN_CORPUS_FACTOR)
    {
        return false;
    }
    minimum_documents = first_probe_candidate_budget *
        II42_AM_FILTER_PREFIX_MIN_CORPUS_FACTOR;

    return root != NULL && root->next_document_slot > minimum_documents;
}

static bool
ii42_am_filter_prefix_next_probe(
    size_t probe_k,
    size_t matched_count,
    size_t requested_k,
    size_t *next_probe_k_out
)
{
    size_t required_probe;
    size_t next_probe_k = 1;

    if (probe_k == 0 || matched_count == 0 ||
        matched_count >= requested_k || matched_count > probe_k ||
        requested_k == 0 || next_probe_k_out == NULL)
    {
        return false;
    }
    if (requested_k > SIZE_MAX / probe_k)
    {
        return false;
    }
    /*
     * The estimate schedules work; actual matches remain the exact gate.
     * Prefixes deeper than the page-native planner's bound are rejected here.
     * At that point resolving the allowed set gives the scorer a measurable
     * forward/BMP alternative instead of repeating near-global ranking work.
     */
    required_probe = (requested_k * probe_k) / matched_count;
    if ((requested_k * probe_k) % matched_count != 0)
    {
        required_probe++;
    }
    if (required_probe > II42_AM_FILTER_PREFIX_MAX_K)
    {
        return false;
    }
    while (next_probe_k < required_probe &&
           next_probe_k < II42_AM_FILTER_PREFIX_MAX_K)
    {
        next_probe_k <<= 1U;
    }
    if (next_probe_k <= probe_k ||
        next_probe_k > II42_AM_FILTER_PREFIX_MAX_K)
    {
        return false;
    }
    *next_probe_k_out = next_probe_k;
    return true;
}

static const char *
ii42_am_semantic_query_route_name(
    bool structured_prefix_complete,
    bool structured_scope_complete,
    const ii42_page_query_stats *stats
)
{
    if (structured_scope_complete)
    {
        return "scope_filter";
    }
    if (structured_prefix_complete || stats->ranked_prefix_query_path)
    {
        return "ranked_prefix";
    }
    if (stats->shared_resident_fold_query_path)
    {
        return "resident_fold";
    }
    if (stats->semantic_accelerator_forward_bounded)
    {
        return "forward_bound";
    }
    if (stats->semantic_accelerator_forward_direct_rows)
    {
        return "forward_rows";
    }
    if (stats->semantic_accelerator_forward_transposed)
    {
        return "forward_transpose";
    }
    if (stats->semantic_accelerator_block_major)
    {
        return "accelerator_block_major";
    }
    if (stats->semantic_accelerator_query_path)
    {
        return "semantic_accelerator";
    }
    if (stats->semantic_bmp_query_path)
    {
        return "semantic_bmp";
    }
    if (stats->materialized_query_path)
    {
        return "materialized";
    }
    if (stats->term_at_a_time_query_path)
    {
        return "term_at_a_time";
    }
    if (stats->ordered_block_query_path)
    {
        return "ordered_block";
    }
    return "page_native";
}

typedef struct ii42_am_semantic_query_trace
{
    char query_route[32];
    uint64 filter_probe_rows;
    uint32 ranked_prefix_probe_attempts;
    uint64 ranked_prefix_probe_documents_examined;
    uint64 ranked_prefix_probe_postings_examined;
    uint64 ranked_prefix_probe_memory_bytes;
    uint32 scope_predicates;
    uint32 scope_resolved_predicates;
    uint64 scope_ilike_comparisons;
    uint64 scope_ilike_values_examined;
    uint64 scope_ilike_blocks_considered;
    uint64 scope_ilike_blocks_skipped;
    uint32 scope_ilike_values;
    uint64 allowed_documents;
    uint64 memory_bytes;
    ii42_page_query_stats query;
    bool sql_filter_residual;
    bool filter_probe_attempted;
    bool filter_probe_complete;
    bool scope_ilike_comparison_limit_exceeded;
    bool valid;
} ii42_am_semantic_query_trace;

static ii42_am_semantic_query_trace ii42_am_last_semantic_query_trace;

static void
ii42_am_semantic_query_trace_reset(void)
{
    memset(
        &ii42_am_last_semantic_query_trace,
        0,
        sizeof(ii42_am_last_semantic_query_trace)
    );
}

static void
ii42_am_semantic_query_trace_finish(
    bool structured_prefix_complete,
    bool structured_scope_complete,
    const ii42_filter_scope_trace *scope_trace,
    bool sql_filter_residual,
    bool filter_probe_attempted,
    bool filter_probe_complete,
    uint64 filter_probe_rows,
    uint64 allowed_documents,
    uint64 memory_bytes,
    const ii42_am_page_native_search_trace *prefix_trace,
    uint32 prefix_attempts,
    const ii42_page_query_stats *route_query,
    const ii42_page_query_stats *query
)
{
    const char *route = ii42_am_semantic_query_route_name(
        structured_prefix_complete,
        structured_scope_complete,
        route_query
    );

    ii42_am_last_semantic_query_trace.scope_predicates =
        scope_trace->predicate_count;
    ii42_am_last_semantic_query_trace.scope_resolved_predicates =
        scope_trace->resolved_predicate_count;
    ii42_am_last_semantic_query_trace.scope_ilike_comparisons =
        scope_trace->ilike_comparisons;
    ii42_am_last_semantic_query_trace.scope_ilike_values_examined =
        scope_trace->ilike_values_examined;
    ii42_am_last_semantic_query_trace.scope_ilike_blocks_considered =
        scope_trace->ilike_blocks_considered;
    ii42_am_last_semantic_query_trace.scope_ilike_blocks_skipped =
        scope_trace->ilike_blocks_skipped;
    ii42_am_last_semantic_query_trace.scope_ilike_values =
        scope_trace->ilike_values;
    ii42_am_last_semantic_query_trace
        .scope_ilike_comparison_limit_exceeded =
            scope_trace->ilike_comparison_limit_exceeded;
    ii42_am_last_semantic_query_trace.sql_filter_residual =
        sql_filter_residual;
    ii42_am_last_semantic_query_trace.filter_probe_attempted =
        filter_probe_attempted;
    ii42_am_last_semantic_query_trace.filter_probe_complete =
        filter_probe_complete;
    ii42_am_last_semantic_query_trace.filter_probe_rows = filter_probe_rows;
    ii42_am_last_semantic_query_trace.allowed_documents = allowed_documents;
    ii42_am_last_semantic_query_trace.memory_bytes = memory_bytes;
    ii42_am_last_semantic_query_trace.ranked_prefix_probe_attempts =
        query->ranked_prefix_probe_attempts;
    ii42_am_last_semantic_query_trace
        .ranked_prefix_probe_documents_examined =
            query->ranked_prefix_probe_documents_examined;
    ii42_am_last_semantic_query_trace
        .ranked_prefix_probe_postings_examined =
            query->ranked_prefix_probe_postings_examined;
    ii42_am_last_semantic_query_trace.ranked_prefix_probe_memory_bytes =
        query->ranked_prefix_probe_memory_bytes;
    if (prefix_trace != NULL && prefix_attempts > 0)
    {
        ii42_am_last_semantic_query_trace.ranked_prefix_probe_attempts =
            ii42_u32_saturating_add(
                ii42_am_last_semantic_query_trace
                    .ranked_prefix_probe_attempts,
                prefix_attempts
            );
        ii42_am_last_semantic_query_trace
            .ranked_prefix_probe_documents_examined =
                ii42_u64_saturating_add(
                    ii42_am_last_semantic_query_trace
                        .ranked_prefix_probe_documents_examined,
                    ii42_am_page_native_probe_document_work(
                        &prefix_trace->query
                    )
                );
        ii42_am_last_semantic_query_trace
            .ranked_prefix_probe_postings_examined =
                ii42_u64_saturating_add(
                    ii42_am_last_semantic_query_trace
                        .ranked_prefix_probe_postings_examined,
                    ii42_am_page_native_probe_posting_work(
                        &prefix_trace->query
                    )
                );
        ii42_am_last_semantic_query_trace.ranked_prefix_probe_memory_bytes =
            Max(
                ii42_am_last_semantic_query_trace
                    .ranked_prefix_probe_memory_bytes,
                prefix_trace->memory_bytes
            );
    }
    ii42_am_last_semantic_query_trace.query = *query;
    if (!structured_prefix_complete &&
        prefix_trace != NULL && prefix_attempts > 0)
    {
        ii42_am_last_semantic_query_trace.query.visibility_rank_attempts =
            ii42_u32_saturating_add(
                query->visibility_rank_attempts,
                prefix_trace->query.visibility_rank_attempts
            );
    }
    strlcpy(
        ii42_am_last_semantic_query_trace.query_route,
        route,
        sizeof(ii42_am_last_semantic_query_trace.query_route)
    );
    ii42_am_last_semantic_query_trace.valid = true;
}

/*
 * A ranked prefix containing k predicate matches completes the bounded
 * approximate accelerator route with exact predicate membership. Otherwise
 * discard it and let the same-root subset scorer complete.
 */
static bool
ii42_am_try_structured_filter_prefix(
    Relation index_relation,
    Relation heap_relation,
    Oid source_type,
    const uint32_t *query_ids,
    const float *query_weights,
    size_t query_len,
    Jsonb *filters,
    size_t requested_k,
    ii42_segment_read_root *root_inout,
    ii42_query_state *state_out,
    ii42_am_page_native_search_trace *trace_out,
    uint32 *attempt_count_out
)
{
    size_t first_probe_k = II42_AM_FILTER_PREFIX_MIN_K;
    bool adaptive_range_prefix;

    if (index_relation == NULL || heap_relation == NULL ||
        query_ids == NULL || query_len == 0 || filters == NULL ||
        requested_k == 0 || root_inout == NULL || state_out == NULL ||
        trace_out == NULL || attempt_count_out == NULL ||
        requested_k > II42_AM_FILTER_PREFIX_MAX_K)
    {
        return false;
    }
    memset(trace_out, 0, sizeof(*trace_out));
    *attempt_count_out = 0;
    adaptive_range_prefix = ii42_filter_is_range_only(filters);
    while (first_probe_k < requested_k &&
           first_probe_k < II42_AM_FILTER_PREFIX_FIRST_MAX_K)
    {
        first_probe_k <<= 1U;
    }
    if (requested_k <= SIZE_MAX / 4U)
    {
        size_t target = requested_k * 4U;

        while (first_probe_k < target &&
               first_probe_k < II42_AM_FILTER_PREFIX_FIRST_MAX_K)
        {
            first_probe_k <<= 1U;
        }
    }
    first_probe_k = Min(
        first_probe_k,
        II42_AM_FILTER_PREFIX_FIRST_MAX_K
    );
    for (size_t probe_k = first_probe_k;;)
    {
        ii42_query_state probe_state = {0};
        ii42_am_page_native_search_trace probe_trace;
        ii42_segment_read_root probe_root;
        bool *matches;
        size_t matched_count = 0;
        size_t retained = 0;

        memset(&probe_trace, 0, sizeof(probe_trace));
        ii42_am_prepare_page_native_search_state_at_root(
            index_relation,
            heap_relation,
            source_type,
            query_ids,
            query_weights,
            NULL,
            NULL,
            NULL,
            query_len,
            true,
            probe_k,
            NULL,
            NULL,
            &probe_root,
            &probe_state,
            &probe_trace
        );
        if (*attempt_count_out < UINT32_MAX)
        {
            (*attempt_count_out)++;
        }
        ii42_am_page_native_stats_accumulate(
            &trace_out->query,
            &probe_trace.query
        );
        trace_out->final_attempt_query =
            probe_trace.final_attempt_query_valid
                ? probe_trace.final_attempt_query
                : probe_trace.query;
        trace_out->final_attempt_query_valid = true;
        trace_out->visible_document_count =
            probe_trace.visible_document_count;
        trace_out->l0_visited_records = probe_trace.l0_visited_records;
        trace_out->l0_visible_records = probe_trace.l0_visible_records;
        trace_out->l0_document_count = probe_trace.l0_document_count;
        trace_out->l0_contribution_count =
            probe_trace.l0_contribution_count;
        trace_out->memory_bytes = Max(
            trace_out->memory_bytes,
            probe_trace.memory_bytes
        );
        *root_inout = probe_root;
        if (probe_state.topk.len == 0)
        {
            ii42_am_search_state_reset(&probe_state);
            return false;
        }
        matches = palloc0(
            sizeof(*matches) * probe_state.topk.len
        );
        ii42_filter_match_tid_candidates(
            heap_relation,
            filters,
            probe_state.tids,
            probe_state.topk.len,
            matches,
            &matched_count
        );
        if (matched_count >= requested_k)
        {
            for (size_t rank = 0;
                 rank < probe_state.topk.len && retained < requested_k;
                 rank++)
            {
                if (!matches[rank])
                {
                    continue;
                }
                probe_state.tids[retained] = probe_state.tids[rank];
                probe_state.topk.doc_ids[retained] =
                    probe_state.topk.doc_ids[rank];
                probe_state.topk.scores[retained] =
                    probe_state.topk.scores[rank];
                retained++;
            }
            probe_state.topk.len = retained;
            pfree(matches);
            *state_out = probe_state;
            return true;
        }
        pfree(matches);
        ii42_am_search_state_reset(&probe_state);
        if (probe_k >= II42_AM_FILTER_PREFIX_MAX_K ||
            !adaptive_range_prefix ||
            !ii42_am_filter_prefix_next_probe(
                probe_k,
                matched_count,
                requested_k,
                &probe_k
            ))
        {
            return false;
        }
    }
}

/*
 * Rank inside the published scope baseline, then make the structured
 * predicate authoritative for every returned heap tuple.  New matching rows
 * outside that baseline may wait for background convergence, but stale
 * members never escape the current statement snapshot.
 */
static void
ii42_am_try_structured_scope_filter(
    Relation index_relation,
    Relation heap_relation,
    Oid source_type,
    const uint32_t *query_ids,
    const float *query_weights,
    size_t query_len,
    Jsonb *filters,
    size_t requested_k,
    const ii42_page_query_filter *scope_filter,
    uint64 scope_allowed_document_count,
    const ii42_segment_read_root *root,
    ii42_query_state *state_out,
    ii42_am_page_native_search_trace *trace_out
)
{
    size_t candidate_k;
    size_t retained = 0;
    size_t matched_count = 0;
    bool *matches;

    if (index_relation == NULL || heap_relation == NULL ||
        query_ids == NULL || query_len == 0 || filters == NULL ||
        requested_k == 0 || scope_filter == NULL || root == NULL ||
        state_out == NULL || trace_out == NULL)
    {
        ereport(ERROR, (errmsg("invalid ii42 structured scope request")));
    }
    candidate_k = requested_k >
        SIZE_MAX / II42_AM_STRUCTURED_SCOPE_OVERFETCH_MULTIPLIER
            ? SIZE_MAX
            : requested_k *
                II42_AM_STRUCTURED_SCOPE_OVERFETCH_MULTIPLIER;
    candidate_k = Min(
        candidate_k,
        scope_allowed_document_count > (uint64) SIZE_MAX
            ? SIZE_MAX
            : (size_t) scope_allowed_document_count
    );
    if (candidate_k == 0)
    {
        memset(state_out, 0, sizeof(*state_out));
        memset(trace_out, 0, sizeof(*trace_out));
        return;
    }
    ii42_am_prepare_page_native_filtered_search_state_at_root(
        index_relation,
        heap_relation,
        source_type,
        query_ids,
        query_weights,
        NULL,
        NULL,
        NULL,
        query_len,
        true,
        candidate_k,
        false,
        scope_filter,
        NULL,
        0,
        GetActiveSnapshot(),
        root,
        NULL,
        state_out,
        trace_out
    );
    if (state_out->topk.len == 0)
    {
        return;
    }
    matches = palloc0(sizeof(*matches) * state_out->topk.len);
    ii42_filter_match_tid_candidates(
        heap_relation,
        filters,
        state_out->tids,
        state_out->topk.len,
        matches,
        &matched_count
    );
    for (size_t rank = 0;
         rank < state_out->topk.len && retained < requested_k;
         rank++)
    {
        if (!matches[rank])
        {
            continue;
        }
        state_out->tids[retained] = state_out->tids[rank];
        state_out->topk.doc_ids[retained] =
            state_out->topk.doc_ids[rank];
        state_out->topk.scores[retained] =
            state_out->topk.scores[rank];
        retained++;
    }
    state_out->topk.len = retained;
    pfree(matches);
}

PG_FUNCTION_INFO_V1(ii42_index_semantic_query_native_internal);
Datum
ii42_index_semantic_query_native_internal(PG_FUNCTION_ARGS)
{
    ii42_am_native_semantic_query_cleanup *cleanup;
    ReturnSetInfo *rsinfo = (ReturnSetInfo *) fcinfo->resultinfo;
    TupleDesc tupdesc;
    Tuplestorestate *tupstore;
    MemoryContext oldcontext;
    Oid index_oid;
    int32 top_k;
    char *expected_signature;
    char runtime_signature[II42_AM_SEMANTIC_SIGNATURE_LEN + 1];
    size_t query_len = 0;
    uint32 selected_terms = 0;
    uint64 entry_visits = 0;
    uint64 decoded_postings = 0;
    uint64 memory_bytes = 0;

    ii42_am_semantic_query_trace_reset();

    if (PG_ARGISNULL(0) || PG_ARGISNULL(1) || PG_ARGISNULL(2) ||
        PG_ARGISNULL(5) || PG_ARGISNULL(6))
    {
        ereport(
            ERROR,
            (
                errmsg(
                    "index, query atoms, query weights, k, and generation "
                    "signature are required"
                )
            )
        );
    }
    if (rsinfo == NULL || !IsA(rsinfo, ReturnSetInfo) ||
        (rsinfo->allowedModes & SFRM_Materialize) == 0)
    {
        ereport(ERROR, (errmsg("materialize mode is required")));
    }
    if (get_call_result_type(fcinfo, NULL, &tupdesc) != TYPEFUNC_COMPOSITE)
    {
        ereport(ERROR, (errmsg("could not resolve result record type")));
    }
    if (tupdesc->natts != II42_AM_SEMANTIC_QUERY_RESULT_COLS)
    {
        ereport(
            ERROR,
            (errmsg("invalid ii42 native semantic result contract"))
        );
    }

    top_k = PG_GETARG_INT32(5);
    if (top_k < 0)
    {
        ereport(ERROR, (errmsg("k must be non-negative")));
    }

    oldcontext = MemoryContextSwitchTo(
        rsinfo->econtext->ecxt_per_query_memory
    );
    cleanup = palloc0(sizeof(*cleanup));
    tupdesc = BlessTupleDesc(CreateTupleDescCopy(tupdesc));
    tupstore = tuplestore_begin_heap(true, false, work_mem);
    rsinfo->returnMode = SFRM_Materialize;
    rsinfo->setResult = tupstore;
    rsinfo->setDesc = tupdesc;

    PG_TRY();
    {
        ii42_am_meta_page meta;
        ii42_am_page_native_search_trace page_trace;
        ii42_am_page_native_search_trace prefix_trace;
        ii42_am_page_native_search_trace scope_candidate_trace;
        ii42_segment_read_root root;
        uint64 candidate_docs;
        uint64 documents_examined;
        const ii42_page_query_stats *route_query;
        size_t rank;
        size_t requested_k;
        Jsonb *structured_filters = NULL;
        uint32 structured_prefix_attempts = 0;
        bool structured_prefix_complete = false;
        bool structured_scope_complete = false;
        bool sql_filter_residual = false;
        bool filter_probe_attempted = false;
        bool filter_probe_complete = false;
        uint64 filter_probe_rows = 0;
        ii42_filter_scope_trace scope_trace = {0};
        ii42_status status;

        memset(&prefix_trace, 0, sizeof(prefix_trace));
        memset(&scope_candidate_trace, 0, sizeof(scope_candidate_trace));
        ii42_init_reloptions();
        index_oid = PG_GETARG_OID(0);
        cleanup->index_relation = index_open(index_oid, AccessShareLock);
        ii42_am_require_index_relation(cleanup->index_relation);
        ii42_am_require_index_read(cleanup->index_relation);
        ii42_am_read_meta(cleanup->index_relation, &meta);
        ii42_am_require_convergent_segment_storage(&meta);
        ii42_am_runtime_signature(
            cleanup->index_relation,
            runtime_signature
        );
        expected_signature = text_to_cstring(PG_GETARG_TEXT_PP(6));
        if (!ii42_am_semantic_signature_valid(expected_signature) ||
            strcmp(expected_signature, runtime_signature) != 0)
        {
            ereport(
                ERROR,
                (
                    errcode(ERRCODE_OBJECT_NOT_IN_PREREQUISITE_STATE),
                    errmsg("ii42 semantic query generation changed"),
                    errdetail(
                        "The query encoder signature does not match the "
                        "active index generation."
                    ),
                    errhint("Encode the query again and retry.")
                )
            );
        }
        cleanup->heap_relation = table_open(
            cleanup->index_relation->rd_index->indrelid,
            AccessShareLock
        );
        if (((PG_NARGS() > 7 && !PG_ARGISNULL(7)) ? 1 : 0) +
            ((PG_NARGS() > 8 && !PG_ARGISNULL(8)) ? 1 : 0) +
            ((PG_NARGS() > 9 && !PG_ARGISNULL(9)) ? 1 : 0) > 1)
        {
            ereport(
                ERROR,
                (
                    errmsg(
                        "allowed document ids, allowed TIDs, and structured "
                        "filters are mutually exclusive"
                    )
                )
            );
        }
        if ((PG_NARGS() > 7 && !PG_ARGISNULL(7)) ||
            (PG_NARGS() > 8 && !PG_ARGISNULL(8)) ||
            (PG_NARGS() > 9 && !PG_ARGISNULL(9)))
        {
            status = ii42_am_segment_read_root_from_meta(&meta, &root);
            if (status != II42_OK)
            {
                ereport(
                    ERROR,
                    (
                        errmsg("invalid ii42 convergent segment root"),
                        errdetail(
                            "Validation failed: %s.",
                            ii42_strerror(status)
                        )
                    )
                );
            }
            if (PG_NARGS() > 7 && !PG_ARGISNULL(7))
            {
                ii42_am_read_document_filter(
                    PG_GETARG_ARRAYTYPE_P(7),
                    root.next_document_slot,
                    &cleanup->allowed_document_bitmap,
                    &cleanup->filter
                );
            }
            else if (PG_NARGS() > 8 && !PG_ARGISNULL(8))
            {
                ii42_am_read_tid_filter(
                    PG_GETARG_ARRAYTYPE_P(8),
                    &cleanup->allowed_tid_keys,
                    &cleanup->allowed_tid_count
                );
                cleanup->tid_filter_active = true;
            }
            else
            {
                structured_filters = PG_GETARG_JSONB_P(9);
            }
            cleanup->filter_active = true;
        }
        ii42_am_read_weighted_query_arrays(
            PG_GETARG_ARRAYTYPE_P(1),
            PG_GETARG_ARRAYTYPE_P(2),
            &cleanup->query_ids,
            &cleanup->query_weights,
            &query_len
        );
        if (ii42_am_field_aware_enabled(cleanup->index_relation))
        {
            const ii42_am_sae_lexical_mapper *mapper =
                ii42_am_get_sae_lexical_mapper(
                    cleanup->index_relation
                );

            if (PG_ARGISNULL(3))
            {
                if (!PG_ARGISNULL(4))
                {
                    ereport(
                        ERROR,
                        (errmsg("field weights require field names"))
                    );
                }
                ii42_am_read_all_field_specs(
                    cleanup->index_relation,
                    &cleanup->field_indexes,
                    &cleanup->field_weights,
                    &cleanup->num_fields
                );
            }
            else
            {
                ii42_am_read_field_specs(
                    cleanup->index_relation,
                    PG_GETARG_ARRAYTYPE_P(3),
                    PG_ARGISNULL(4)
                        ? NULL
                        : PG_GETARG_ARRAYTYPE_P(4),
                    &cleanup->field_indexes,
                    &cleanup->field_weights,
                    &cleanup->num_fields
                );
            }

            ii42_am_remap_field_aware_semantic_query(
                &mapper->contract,
                cleanup->field_indexes,
                cleanup->field_weights,
                cleanup->num_fields,
                &cleanup->query_ids,
                &cleanup->query_weights,
                &query_len
            );
        }
        else if (!PG_ARGISNULL(3) || !PG_ARGISNULL(4))
        {
            ereport(
                ERROR,
                (errmsg("field-aware search requires field_aware=true"))
            );
        }
        requested_k = (size_t) top_k;
        if (structured_filters != NULL)
        {
            bool scope_filter_fully_resolved = false;
            bool scope_predicates_fully_resolved = false;
            bool scope_filter_resolved;

            scope_trace.predicate_count =
                (uint32) JB_ROOT_COUNT(structured_filters);
            scope_filter_resolved = ii42_filter_try_scope_bitmap(
                cleanup->index_relation,
                cleanup->heap_relation,
                &root,
                structured_filters,
                &cleanup->allowed_document_bitmap,
                &cleanup->filter.document_slot_count,
                &cleanup->filter.allowed_document_count,
                &scope_filter_fully_resolved,
                &scope_trace
            );
            if (scope_filter_resolved)
            {
                scope_filter_resolved =
                    ii42_am_align_scope_filter_with_root(
                        &cleanup->allowed_document_bitmap,
                        cleanup->filter.document_slot_count,
                        cleanup->filter.allowed_document_count,
                        &root,
                        &cleanup->filter
                    );
                scope_predicates_fully_resolved =
                    scope_trace.predicate_count > 0 &&
                    scope_trace.resolved_predicate_count ==
                        scope_trace.predicate_count;
                if (scope_filter_resolved &&
                    scope_predicates_fully_resolved &&
                    !ii42_semantic_accelerator_disabled &&
                    !ii42_test_force_semantic_bmp)
                {
                    ii42_am_try_structured_scope_filter(
                        cleanup->index_relation,
                        cleanup->heap_relation,
                        meta.source_type,
                        cleanup->query_ids,
                        cleanup->query_weights,
                        query_len,
                        structured_filters,
                        requested_k,
                        &cleanup->filter,
                        cleanup->filter.allowed_document_count,
                        &root,
                        &cleanup->state,
                        &scope_candidate_trace
                    );
                    structured_scope_complete = true;
                }
                else if (scope_filter_resolved &&
                         !scope_filter_fully_resolved)
                {
                    /* Hidden exact A/B mode must include post-baseline rows. */
                    cleanup->filter.allowed_document_bitmap = NULL;
                }
            }
            if (!ii42_test_force_semantic_bmp &&
                !structured_scope_complete &&
                !scope_filter_resolved)
            {
                filter_probe_attempted = true;
                filter_probe_complete = ii42_filter_collect_tid_keys(
                    cleanup->heap_relation,
                    structured_filters,
                    0,
                    II42_AM_FILTER_RESOLVE_MAX_ROWS,
                    &cleanup->allowed_tid_keys,
                    &cleanup->allowed_tid_count
                );
                filter_probe_rows = cleanup->allowed_tid_count;

                if (filter_probe_complete)
                {
                    cleanup->tid_filter_active = true;
                    sql_filter_residual = true;
                }
                else
                {
                    pfree(cleanup->allowed_tid_keys);
                    cleanup->allowed_tid_keys = NULL;
                    cleanup->allowed_tid_count = 0;
                }
            }
            /* No scope exists, so retain the bounded global-prefix fallback. */
            if (!structured_scope_complete &&
                !ii42_test_force_semantic_bmp &&
                !scope_filter_resolved &&
                !cleanup->tid_filter_active &&
                ii42_am_filter_prefix_has_physical_leverage(&root))
            {
                structured_prefix_complete =
                    ii42_am_try_structured_filter_prefix(
                        cleanup->index_relation,
                        cleanup->heap_relation,
                        meta.source_type,
                        cleanup->query_ids,
                        cleanup->query_weights,
                        query_len,
                        structured_filters,
                        requested_k,
                        &root,
                        &cleanup->state,
                        &prefix_trace,
                        &structured_prefix_attempts
                    );
            }
            if (structured_scope_complete)
            {
                page_trace = scope_candidate_trace;
            }
            else if (structured_prefix_complete)
            {
                page_trace = prefix_trace;
            }
            if (!structured_scope_complete &&
                !structured_prefix_complete)
            {
                if (scope_filter_resolved &&
                    scope_filter_fully_resolved)
                {
                    /* A current scope bitmap is already exact. */
                }
                else
                {
                    if (ii42_am_test_setting_enabled(
                            "ii42.test_require_scope_filter",
                            "scope filter") &&
                        !scope_filter_resolved)
                    {
                        ereport(
                            ERROR,
                            (errmsg(
                                "required ii42 scope filter was unavailable"
                            ))
                        );
                    }
                    if (!cleanup->tid_filter_active)
                    {
                        (void) ii42_filter_collect_tid_keys(
                            cleanup->heap_relation,
                            structured_filters,
                            scope_filter_resolved
                                ? cleanup->filter.allowed_document_count
                                : 0,
                            0,
                            &cleanup->allowed_tid_keys,
                            &cleanup->allowed_tid_count
                        );
                        sql_filter_residual = true;
                        cleanup->tid_filter_active = true;
                    }
                }
            }
        }
        if (structured_scope_complete)
        {
            /* The serving scope produced bounded, current-checked matches. */
        }
        else if (structured_prefix_complete)
        {
            /* The ranked prefix completed the bounded approximate route. */
        }
        else if (cleanup->filter_active)
        {
            uint64 allowed_count = cleanup->tid_filter_active
                ? (uint64) cleanup->allowed_tid_count
                : cleanup->filter.allowed_document_count;

            requested_k = Min(
                requested_k,
                allowed_count > (uint64) SIZE_MAX
                    ? SIZE_MAX
                    : (size_t) allowed_count
            );
            ii42_am_prepare_page_native_filtered_search_state_at_root(
                cleanup->index_relation,
                cleanup->heap_relation,
                meta.source_type,
                cleanup->query_ids,
                cleanup->query_weights,
                NULL,
                NULL,
                NULL,
                query_len,
                true,
                requested_k,
                structured_prefix_attempts > 0,
                cleanup->filter.allowed_document_bitmap != NULL
                    ? &cleanup->filter
                    : NULL,
                cleanup->tid_filter_active
                    ? cleanup->allowed_tid_keys
                    : NULL,
                cleanup->allowed_tid_count,
                NULL,
                &root,
                NULL,
                &cleanup->state,
                &page_trace
            );
        }
        else
        {
            ii42_am_prepare_page_native_search_state(
                cleanup->index_relation,
                cleanup->heap_relation,
                meta.source_type,
                cleanup->query_ids,
                cleanup->query_weights,
                NULL,
                query_len,
                true,
                requested_k,
                &cleanup->state,
                &page_trace
            );
        }

        candidate_docs = page_trace.visible_document_count;
        documents_examined = page_trace.query.documents_examined;
        if (!page_trace.query.ranked_prefix_query_path)
        {
            documents_examined = ii42_u64_saturating_add(
                documents_examined,
                page_trace.query.ranked_prefix_probe_documents_examined
            );
        }
        if (!structured_prefix_complete &&
            structured_prefix_attempts > 0)
        {
            documents_examined = ii42_u64_saturating_add(
                documents_examined,
                ii42_am_page_native_probe_document_work(
                    &prefix_trace.query
                )
            );
        }
        if (candidate_docs > (uint64) INT_MAX ||
            documents_examined > (uint64) INT_MAX ||
            query_len > (size_t) INT_MAX)
        {
            ereport(
                ERROR,
                (errmsg("ii42 native semantic trace exceeds SQL int4 limits"))
            );
        }
        selected_terms = page_trace.query.query_term_count;
        entry_visits = page_trace.query.query_run_count;
        decoded_postings = page_trace.query.postings_examined;
        memory_bytes = page_trace.memory_bytes;
        if (!page_trace.query.ranked_prefix_query_path)
        {
            decoded_postings = ii42_u64_saturating_add(
                decoded_postings,
                page_trace.query.ranked_prefix_probe_postings_examined
            );
        }
        memory_bytes = Max(
            memory_bytes,
            page_trace.query.ranked_prefix_probe_memory_bytes
        );
        if (!structured_prefix_complete &&
            structured_prefix_attempts > 0)
        {
            entry_visits = ii42_u64_saturating_add(
                entry_visits,
                prefix_trace.query.query_run_count
            );
            decoded_postings = ii42_u64_saturating_add(
                decoded_postings,
                ii42_am_page_native_probe_posting_work(
                    &prefix_trace.query
                )
            );
            memory_bytes = Max(memory_bytes, prefix_trace.memory_bytes);
        }
        route_query = page_trace.final_attempt_query_valid
            ? &page_trace.final_attempt_query
            : &page_trace.query;
        ii42_am_semantic_query_trace_finish(
            structured_prefix_complete,
            structured_scope_complete,
            &scope_trace,
            sql_filter_residual,
            filter_probe_attempted,
            filter_probe_complete,
            filter_probe_rows,
            cleanup->tid_filter_active
                ? (uint64) cleanup->allowed_tid_count
                : cleanup->filter.allowed_document_count,
            memory_bytes,
            structured_prefix_attempts > 0 ? &prefix_trace : NULL,
            structured_prefix_attempts,
            route_query,
            &page_trace.query
        );
        for (rank = 0; rank < cleanup->state.topk.len; rank++)
        {
            Datum values[II42_AM_SEMANTIC_QUERY_RESULT_COLS];
            bool nulls[II42_AM_SEMANTIC_QUERY_RESULT_COLS] = {false};

            values[0] = Int32GetDatum((int32) rank + 1);
            values[1] = ItemPointerGetDatum(&cleanup->state.tids[rank]);
            values[2] = Int32GetDatum(
                (int32) cleanup->state.topk.doc_ids[rank]
            );
            values[3] = Float8GetDatum(
                (double) cleanup->state.topk.scores[rank]
            );
            values[4] = Int32GetDatum((int32) selected_terms);
            values[5] = Int32GetDatum((int32) candidate_docs);
            values[6] = Int32GetDatum(
                (int32) documents_examined
            );
            values[7] = Int64GetDatum(ii42_am_trace_i64(entry_visits));
            values[8] = Int64GetDatum(
                ii42_am_trace_i64(decoded_postings)
            );
            values[9] = Int64GetDatum(
                ii42_am_trace_i64(decoded_postings)
            );
            values[10] = Int64GetDatum(0);
            values[11] = Int64GetDatum(0);
            values[12] = Int64GetDatum(0);
            values[13] = Int64GetDatum(0);
            values[14] = Int64GetDatum(ii42_am_trace_i64(memory_bytes));
            tuplestore_putvalues(tupstore, tupdesc, values, nulls);
        }
    }
    PG_FINALLY();
    {
        ii42_am_native_semantic_query_cleanup_free(cleanup);
        pfree(cleanup);
    }
    PG_END_TRY();

    MemoryContextSwitchTo(oldcontext);
    return (Datum) 0;
}

