PG_FUNCTION_INFO_V1(ii42_query_bm25_internal);
Datum
ii42_query_bm25_internal(PG_FUNCTION_ARGS)
{
    FuncCallContext *funcctx;
    ii42_query_state *state;

    if (SRF_IS_FIRSTCALL())
    {
        MemoryContext oldcontext;
        Oid index_oid = PG_GETARG_OID(0);
        text *query_text = PG_GETARG_TEXT_PP(1);
        int32 k = PG_GETARG_INT32(2);
        ArrayType *weight_mask = PG_ARGISNULL(3) ? NULL : PG_GETARG_ARRAYTYPE_P(3);
        bool lowercase_isnull = PG_ARGISNULL(4);
        bool lowercase = lowercase_isnull ? false : PG_GETARG_BOOL(4);
        bool stopwords_isnull = PG_ARGISNULL(5);
        ArrayType *stopwords_array = PG_ARGISNULL(5) ? NULL : PG_GETARG_ARRAYTYPE_P(5);
        bool stem_english_isnull = PG_ARGISNULL(6);
        bool stem_english = stem_english_isnull ? false : PG_GETARG_BOOL(6);
        bool fold_diacritics_isnull = PG_ARGISNULL(7);
        bool fold_diacritics = fold_diacritics_isnull ? false : PG_GETARG_BOOL(7);
        Relation indexRelation;
        Relation heapRelation;
        ii42_am_cache_entry *entry;
        ii42_am_meta_page meta;
        ii42_am_page_native_search_trace page_trace;
        Oid source_type;
        ii42_text_options options;
        char **stopwords = NULL;
        size_t stopword_len = 0;
        ii42_am_direct_search_cleanup *cleanup;

        ii42_init_reloptions();
        if (k < 0)
        {
            ereport(ERROR, (errmsg("k must be non-negative")));
        }

        funcctx = SRF_FIRSTCALL_INIT();
        oldcontext = MemoryContextSwitchTo(funcctx->multi_call_memory_ctx);
        state = palloc0(sizeof(*state));
        cleanup = palloc0(sizeof(*cleanup));
        cleanup->caller_context = oldcontext;
        cleanup->state = state;

        PG_TRY();
        {
            indexRelation = index_open(index_oid, AccessShareLock);
            cleanup->index_relation = indexRelation;
            ii42_am_require_index_relation(indexRelation);
            ii42_am_require_index_read(indexRelation);
            source_type = ii42_am_require_textlike_source_type(
                indexRelation,
                "ii42 raw queries require a text[], varchar[], text, or "
                "varchar index"
            );

            if (ii42_am_source_type_is_scalar_text(source_type) &&
                (lowercase_isnull ||
                 stopwords_isnull ||
                 stem_english_isnull ||
                 fold_diacritics_isnull))
            {
                ii42_text_options index_options;
                char **index_stopwords = NULL;
                size_t index_stopword_len = 0;

                ii42_am_read_index_text_options(
                    indexRelation,
                    &index_options,
                    &index_stopwords,
                    &index_stopword_len
                );
                if (lowercase_isnull)
                {
                    lowercase = index_options.lowercase;
                }
                if (stem_english_isnull)
                {
                    stem_english = index_options.stem_english;
                }
                if (fold_diacritics_isnull)
                {
                    fold_diacritics = index_options.fold_diacritics;
                }

                if (stopwords_isnull)
                {
                    ii42_am_finalize_text_options(
                        lowercase,
                        stem_english,
                        fold_diacritics,
                        index_stopwords,
                        index_stopword_len,
                        &options,
                        &stopwords,
                        &stopword_len
                    );
                }
                else
                {
                    ii42_am_free_query_tokens(
                        index_stopwords,
                        index_stopword_len
                    );
                    ii42_am_read_text_options(
                        lowercase,
                        stem_english,
                        fold_diacritics,
                        stopwords_array,
                        &options,
                        &stopwords,
                        &stopword_len
                    );
                }
            }
            else
            {
                ii42_am_read_text_options(
                    lowercase,
                    stem_english,
                    fold_diacritics,
                    stopwords_array,
                    &options,
                    &stopwords,
                    &stopword_len
                );
            }
            cleanup->stopwords = stopwords;
            cleanup->stopword_len = stopword_len;

            heapRelation = table_open(
                indexRelation->rd_index->indrelid,
                AccessShareLock
            );
            cleanup->heap_relation = heapRelation;
            ii42_am_read_meta(indexRelation, &meta);
            ii42_am_require_exact_bm25_index_at_meta(
                indexRelation,
                &meta
            );
            if (weight_mask == NULL &&
                !ii42_am_no_shared_runtime_bm25_fallback_admitted(
                    indexRelation))
            {
                size_t query_len;

                ii42_query_init(&cleanup->parsed_query);
                cleanup->parsed_query_initialized = true;
                ii42_am_parse_raw_query_with_options(
                    query_text,
                    &options,
                    &cleanup->parsed_query
                );
                if (cleanup->parsed_query.len == 0)
                {
                    ereport(
                        ERROR,
                        (errmsg("query produced no searchable tokens"))
                    );
                }
                if (ii42_am_field_aware_enabled(indexRelation) &&
                    !ii42_query_is_simple_term_query(
                        &cleanup->parsed_query))
                {
                    ereport(
                        ERROR,
                        (
                            errmsg(
                                "field-aware generic raw queries support "
                                "simple terms only"
                            ),
                            errhint(
                                "Use ii42_query() with explicit field "
                                "names for field-aware weighted retrieval."
                            )
                        )
                    );
                }
                if (ii42_query_is_simple_term_query(
                        &cleanup->parsed_query))
                {
                    query_len = cleanup->parsed_query.len;
                    cleanup->parsed_query_tokens = palloc(
                        sizeof(*cleanup->parsed_query_tokens) * query_len
                    );
                    for (size_t query_index = 0;
                         query_index < query_len;
                         query_index++)
                    {
                        cleanup->parsed_query_tokens[query_index] =
                            cleanup->parsed_query.terms[query_index].tokens[0];
                    }
                    if (ii42_am_field_aware_enabled(indexRelation))
                    {
                        size_t num_fields;

                        ii42_am_read_all_field_specs(
                            indexRelation,
                            &cleanup->field_indexes,
                            &cleanup->field_weights,
                            &num_fields
                        );
                        ii42_am_build_field_query(
                            cleanup->parsed_query_tokens,
                            query_len,
                            cleanup->field_indexes,
                            cleanup->field_weights,
                            num_fields,
                            &cleanup->field_query_tokens,
                            &cleanup->field_query_weights,
                            &cleanup->field_query_len
                        );
                        ii42_am_prepare_page_native_search_state(
                            indexRelation,
                            heapRelation,
                            source_type,
                            NULL,
                            cleanup->field_query_weights,
                            (const char *const *)
                                cleanup->field_query_tokens,
                            cleanup->field_query_len,
                            false,
                            (size_t) k,
                            state,
                            &page_trace
                        );
                    }
                    else
                    {
                        ii42_am_prepare_page_native_search_state(
                            indexRelation,
                            heapRelation,
                            source_type,
                            NULL,
                            NULL,
                            (const char *const *)
                                cleanup->parsed_query_tokens,
                            query_len,
                            false,
                            (size_t) k,
                            state,
                            &page_trace
                        );
                    }
                }
                else
                {
                    ii42_am_prepare_page_native_verified_query_search_state(
                        indexRelation,
                        heapRelation,
                        source_type,
                        &cleanup->parsed_query,
                        (size_t) k,
                        GetActiveSnapshot(),
                        state,
                        &page_trace
                    );
                }
            }
            else
            {
                if (weight_mask != NULL)
                {
                    ii42_am_require_bounded_bm25_snapshot(
                        indexRelation,
                        "weight_mask"
                    );
                }
                entry = ii42_am_get_cached_segment_index(
                    indexRelation,
                    source_type,
                    &meta
                );
                cleanup->entry = entry;
                ii42_am_prepare_raw_query_search_state_with_options(
                    entry,
                    indexRelation,
                    heapRelation,
                    query_text,
                    &options,
                    weight_mask,
                    (size_t) k,
                    weight_mask != NULL ||
                        ii42_am_field_aware_enabled(indexRelation),
                    state
                );
            }

            funcctx->user_fctx = state;
            if (get_call_result_type(
                    fcinfo,
                    NULL,
                    &funcctx->tuple_desc
                ) != TYPEFUNC_COMPOSITE)
            {
                ereport(
                    ERROR,
                    (errmsg("could not resolve result record type"))
                );
            }
            BlessTupleDesc(funcctx->tuple_desc);
            ii42_am_search_state_register_cleanup(
                funcctx->multi_call_memory_ctx,
                state
            );
            cleanup->state_transferred = true;
            ii42_am_direct_search_cleanup_free(cleanup);
        }
        PG_CATCH();
        {
            ii42_am_direct_search_cleanup_free(cleanup);
            pfree(cleanup);
            PG_RE_THROW();
        }
        PG_END_TRY();
        pfree(cleanup);
    }

    funcctx = SRF_PERCALL_SETUP();
    state = funcctx->user_fctx;

    if (state->pos < state->topk.len)
    {
        Datum values[3];
        bool nulls[3] = {false, false, false};
        HeapTuple tuple;
        size_t pos = state->pos++;

        values[0] = ItemPointerGetDatum(&state->tids[pos]);
        values[1] = Int32GetDatum((int32) state->topk.doc_ids[pos]);
        values[2] = Float4GetDatum(state->topk.scores[pos]);
        tuple = heap_form_tuple(funcctx->tuple_desc, values, nulls);
        SRF_RETURN_NEXT(funcctx, HeapTupleGetDatum(tuple));
    }

    ii42_am_search_state_finish(state);
    funcctx->user_fctx = NULL;
    SRF_RETURN_DONE(funcctx);
}
